import { PostgreSqlContainer, type StartedPostgreSqlContainer } from '@testcontainers/postgresql'
import { Client } from 'pg'
import type { ProvidedContext } from 'vitest'

export const POSTGRES_CAPACITY_IMAGE = 'postgres:16-alpine'

let container: StartedPostgreSqlContainer | undefined

interface GlobalSetupContext {
  provide<K extends keyof ProvidedContext & string>(key: K, value: ProvidedContext[K]): void
}

export async function setup({ provide }: GlobalSetupContext): Promise<void> {
  container = await new PostgreSqlContainer(POSTGRES_CAPACITY_IMAGE).start()
  const databaseUrl = container.getConnectionUri()
  const client = new Client({ connectionString: databaseUrl })
  try {
    await client.connect()
    const result = await client.query<{ server_version: string }>('SHOW server_version')
    const postgresVersion = result.rows[0]?.server_version
    if (!postgresVersion) throw new Error('PostgreSQL did not return server_version')
    provide('postgresCapacityDatabaseUrl', databaseUrl)
    provide('postgresCapacityImage', POSTGRES_CAPACITY_IMAGE)
    provide('postgresCapacityVersion', postgresVersion)
  } catch (error) {
    await container.stop()
    container = undefined
    throw error
  } finally {
    await client.end().catch(() => undefined)
  }
}

export async function teardown(): Promise<void> {
  await container?.stop()
  container = undefined
}

declare module 'vitest' {
  export interface ProvidedContext {
    postgresCapacityDatabaseUrl: string
    postgresCapacityImage: string
    postgresCapacityVersion: string
  }
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

const auth = vi.hoisted(() => ({
  getToken: vi.fn(),
  getIdTokenRaw: vi.fn(),
  getUser: vi.fn(),
  refreshTokenAfterUnauthorized: vi.fn(),
  redirectExpiredSession: vi.fn(),
  signOutDeletedAccount: vi.fn()
}))

vi.mock('@/lib/auth', () => auth)

describe('Control Plane authentication recovery', () => {
  beforeEach(() => {
    vi.resetModules()
    auth.getToken.mockReset().mockResolvedValueOnce('rejected-token').mockResolvedValue('fresh-token')
    auth.getIdTokenRaw.mockReset().mockResolvedValue(undefined)
    auth.getUser.mockReset().mockResolvedValue(null)
    auth.refreshTokenAfterUnauthorized.mockReset().mockResolvedValue('fresh-token')
    auth.redirectExpiredSession.mockReset().mockResolvedValue(undefined)
    auth.signOutDeletedAccount.mockReset().mockResolvedValue(undefined)
  })

  afterEach(() => vi.unstubAllGlobals())

  it('forces a token refresh and retries a rejected GET once', async () => {
    const fetchImpl = vi
      .fn()
      .mockResolvedValueOnce(new Response('{}', { status: 401, headers: { 'content-type': 'application/json' } }))
      .mockResolvedValueOnce(
        new Response(JSON.stringify({ identities: [], hasSecurityVerificationMethod: false }), {
          status: 200,
          headers: { 'content-type': 'application/json' }
        })
      )
    vi.stubGlobal('fetch', fetchImpl)
    const { fetchMySocialAccount } = await import('./api')

    await expect(fetchMySocialAccount()).resolves.toEqual({
      identities: [],
      hasSecurityVerificationMethod: false
    })

    expect(auth.refreshTokenAfterUnauthorized).toHaveBeenCalledWith('rejected-token')
    expect(fetchImpl).toHaveBeenCalledTimes(2)
    expect((fetchImpl.mock.calls[0]?.[1]?.headers as Record<string, string>).authorization).toBe(
      'Bearer rejected-token'
    )
    expect((fetchImpl.mock.calls[1]?.[1]?.headers as Record<string, string>).authorization).toBe('Bearer fresh-token')
    expect(auth.redirectExpiredSession).not.toHaveBeenCalled()
  })

  it('returns to sign-in when the refreshed token is rejected too', async () => {
    const fetchImpl = vi.fn(async () =>
      Promise.resolve(new Response('{}', { status: 401, headers: { 'content-type': 'application/json' } }))
    )
    vi.stubGlobal('fetch', fetchImpl)
    const { fetchMySocialAccount } = await import('./api')

    await expect(fetchMySocialAccount()).rejects.toMatchObject({ status: 401 })

    expect(fetchImpl).toHaveBeenCalledTimes(2)
    expect(auth.redirectExpiredSession).toHaveBeenCalledOnce()
  })

  it('does not refresh when the Control Plane says the account was deleted', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn(async () =>
        Promise.resolve(
          new Response(JSON.stringify({ code: 'ACCOUNT_GONE', message: 'account deleted' }), {
            status: 401,
            headers: { 'content-type': 'application/json' }
          })
        )
      )
    )
    const { fetchMySocialAccount } = await import('./api')

    await expect(fetchMySocialAccount()).rejects.toMatchObject({ status: 401, code: 'ACCOUNT_GONE' })

    expect(auth.refreshTokenAfterUnauthorized).not.toHaveBeenCalled()
    expect(auth.signOutDeletedAccount).toHaveBeenCalledOnce()
  })
})

import { describe, expect, it, vi } from 'vitest'

import {
  createEventLoopDriftSampler,
  deriveCapacity,
  measureWithTimeout,
  nearestRankPercentile,
  parseCapacitySettings,
  summarizeDurations,
  validateRungAccounting,
  type RungSummary
} from './postgres-capacity-support.js'

describe('parseCapacitySettings', () => {
  it('uses documented defaults', () => {
    expect(parseCapacitySettings({})).toEqual({
      concurrency: [1, 2, 4, 8, 16, 32, 64],
      minTurns: 100,
      minWaves: 4,
      streamDelayMs: 5,
      asyncPoolSize: 16,
      turnTimeoutMs: 30_000
    })
  })

  it('parses valid overrides', () => {
    expect(
      parseCapacitySettings({
        AC_PG_CAPACITY_CONCURRENCY: '2, 5,9',
        AC_PG_CAPACITY_MIN_TURNS: '250',
        AC_PG_CAPACITY_MIN_WAVES: '7',
        AC_PG_CAPACITY_STREAM_DELAY_MS: '0',
        AC_PG_CAPACITY_ASYNC_POOL_SIZE: '3',
        AC_PG_CAPACITY_TURN_TIMEOUT_MS: '1500'
      })
    ).toEqual({
      concurrency: [2, 5, 9],
      minTurns: 250,
      minWaves: 7,
      streamDelayMs: 0,
      asyncPoolSize: 3,
      turnTimeoutMs: 1500
    })
  })

  it.each([
    ['AC_PG_CAPACITY_CONCURRENCY', ''],
    ['AC_PG_CAPACITY_CONCURRENCY', '1,1'],
    ['AC_PG_CAPACITY_CONCURRENCY', '2,1'],
    ['AC_PG_CAPACITY_CONCURRENCY', '1,0'],
    ['AC_PG_CAPACITY_CONCURRENCY', '1,2.5'],
    ['AC_PG_CAPACITY_CONCURRENCY', '1,9007199254740992'],
    ['AC_PG_CAPACITY_MIN_TURNS', '99'],
    ['AC_PG_CAPACITY_MIN_WAVES', '3'],
    ['AC_PG_CAPACITY_STREAM_DELAY_MS', '-1'],
    ['AC_PG_CAPACITY_ASYNC_POOL_SIZE', '0'],
    ['AC_PG_CAPACITY_TURN_TIMEOUT_MS', '999'],
    ['AC_PG_CAPACITY_MIN_TURNS', '100.5'],
    ['AC_PG_CAPACITY_MIN_TURNS', ' 100']
  ])('rejects invalid %s=%s', (key, value) => {
    expect(() => parseCapacitySettings({ [key]: value })).toThrow(key)
  })
})

describe('duration percentiles', () => {
  it('uses the nearest-rank definition without mutating input', () => {
    const values = [40, 10, 30, 20]
    expect(nearestRankPercentile(values, 50)).toBe(20)
    expect(nearestRankPercentile(values, 95)).toBe(40)
    expect(values).toEqual([40, 10, 30, 20])
  })

  it('summarizes ordered p50, p95, and p99', () => {
    const values = Array.from({ length: 100 }, (_, index) => index + 1)
    expect(summarizeDurations(values)).toEqual({ p50: 50, p95: 95, p99: 99 })
  })

  it.each([
    [[], 50],
    [[1], 0],
    [[1], 101],
    [[-1], 50],
    [[Number.NaN], 50],
    [[Number.POSITIVE_INFINITY], 50]
  ])('rejects invalid values or percentile', (values, percentile) => {
    expect(() => nearestRankPercentile(values, percentile)).toThrow()
  })
})

describe('event-loop drift sampler', () => {
  it('records recurring drift and a final stop sample, then clears its timer', () => {
    let now = 100
    let callback: (() => void) | undefined
    const clearInterval = vi.fn()
    const sampler = createEventLoopDriftSampler({
      now: () => now,
      setInterval: (fn, delay) => {
        expect(delay).toBe(10)
        callback = fn
        return 42
      },
      clearInterval
    })

    now = 113
    callback?.()
    now = 119
    callback?.()
    now = 127
    expect(sampler.stop()).toEqual([3, 0, 0])
    expect(clearInterval).toHaveBeenCalledOnce()
    expect(clearInterval).toHaveBeenCalledWith(42)
    expect(sampler.stop()).toEqual([3, 0, 0])
  })

  it('recovers after one delayed tick when later callbacks resume normal cadence', () => {
    let now = 100
    let callback: (() => void) | undefined
    const sampler = createEventLoopDriftSampler({
      now: () => now,
      setInterval: (fn) => {
        callback = fn
        return 42
      },
      clearInterval: vi.fn()
    })

    now = 130
    callback?.()
    now = 140
    callback?.()
    now = 150
    expect(sampler.stop()).toEqual([20, 0, 0])
  })
})

describe('measureWithTimeout', () => {
  it('classifies normal completion', async () => {
    await expect(measureWithTimeout(async () => 'ok', 1000)).resolves.toMatchObject({
      status: 'completed',
      value: 'ok'
    })
  })

  it('classifies an operation error', async () => {
    const error = new Error('boom')
    await expect(measureWithTimeout(async () => Promise.reject(error), 1000)).resolves.toMatchObject({
      status: 'error',
      error
    })
  })

  it('classifies a timer-race timeout and consumes a later rejection', async () => {
    let rejectOperation!: (error: Error) => void
    const operation = new Promise<never>((_resolve, reject) => {
      rejectOperation = reject
    })
    const resultPromise = measureWithTimeout(() => operation, 5)
    await expect(resultPromise).resolves.toMatchObject({ status: 'timeout' })
    rejectOperation(new Error('late'))
    await Promise.resolve()
  })

  it('classifies elapsed-wall-time timeout when the timer callback was delayed', async () => {
    let now = 0
    const result = await measureWithTimeout(
      async () => {
        now = 1500
        return 'late'
      },
      1000,
      {
        now: () => now,
        setTimeout: () => 7,
        clearTimeout: vi.fn()
      }
    )
    expect(result).toEqual({ status: 'timeout', elapsedMs: 1500 })
  })
})

function rung(overrides: Partial<RungSummary> = {}): RungSummary {
  return {
    concurrency: 1,
    attempted: 100,
    completed: 100,
    errors: 0,
    timeouts: 0,
    throughput: 100,
    infrastructureLatency: { p50: 10, p95: 10, p99: 10 },
    eventLoopDelay: { p50: 0, p95: 0, p99: 0 },
    ...overrides
  }
}

describe('rung accounting', () => {
  it('accepts exact accounting and rejects mismatches or invalid counts', () => {
    expect(() => validateRungAccounting(rung())).not.toThrow()
    expect(() => validateRungAccounting(rung({ completed: 99 }))).toThrow('accounting')
    expect(() => validateRungAccounting(rung({ errors: -1, completed: 101 }))).toThrow()
  })
})

describe('deriveCapacity', () => {
  it.each([
    ['infrastructure-latency', rung({ concurrency: 2, infrastructureLatency: { p50: 10, p95: 21, p99: 21 } })],
    ['throughput-gain', rung({ concurrency: 2, throughput: 119 })],
    ['event-loop-delay', rung({ concurrency: 2, throughput: 130, eventLoopDelay: { p50: 0, p95: 0, p99: 1001 } })],
    ['errors-or-timeouts', rung({ concurrency: 2, throughput: 130, completed: 99, errors: 1 })],
    ['errors-or-timeouts', rung({ concurrency: 2, throughput: 130, completed: 99, timeouts: 1 })]
  ])('detects %s saturation', (reason, saturated) => {
    expect(deriveCapacity([rung(), saturated])).toEqual({
      kind: 'measured',
      concurrency: 1,
      saturatedAt: 2,
      reason
    })
  })

  it('uses the concurrency-1 latency baseline at later rungs', () => {
    expect(
      deriveCapacity([
        rung(),
        rung({ concurrency: 2, throughput: 130, infrastructureLatency: { p50: 10, p95: 19, p99: 19 } }),
        rung({ concurrency: 4, throughput: 170, infrastructureLatency: { p50: 10, p95: 21, p99: 21 } })
      ])
    ).toMatchObject({ kind: 'measured', concurrency: 2, reason: 'infrastructure-latency' })
  })

  it('reports below range when the first rung has failures', () => {
    expect(deriveCapacity([rung({ completed: 99, errors: 1 })])).toEqual({
      kind: 'below-range',
      saturatedAt: 1,
      reason: 'errors-or-timeouts'
    })
  })

  it('reports at least the bound when no rung saturates', () => {
    expect(deriveCapacity([rung(), rung({ concurrency: 2, throughput: 130 })])).toEqual({
      kind: 'at-least',
      concurrency: 2
    })
  })

  it('does not saturate at exact threshold boundaries', () => {
    expect(
      deriveCapacity([
        rung(),
        rung({
          concurrency: 2,
          throughput: 120,
          infrastructureLatency: { p50: 10, p95: 20, p99: 20 },
          eventLoopDelay: { p50: 0, p95: 0, p99: 1000 }
        })
      ])
    ).toEqual({ kind: 'at-least', concurrency: 2 })
  })

  it('uses the specified reason precedence when triggers are simultaneous', () => {
    expect(
      deriveCapacity([
        rung(),
        rung({
          concurrency: 2,
          throughput: 100,
          infrastructureLatency: { p50: 10, p95: 21, p99: 21 },
          eventLoopDelay: { p50: 0, p95: 0, p99: 1001 },
          completed: 99,
          errors: 1
        })
      ])
    ).toMatchObject({ reason: 'infrastructure-latency' })
  })

  it('prefers throughput gain over simultaneous event-loop and failure triggers', () => {
    expect(
      deriveCapacity([
        rung(),
        rung({
          concurrency: 2,
          throughput: 119,
          eventLoopDelay: { p50: 0, p95: 0, p99: 1001 },
          completed: 99,
          errors: 1
        })
      ])
    ).toMatchObject({ reason: 'throughput-gain' })
  })

  it('prefers event-loop delay over simultaneous failure triggers', () => {
    expect(
      deriveCapacity([
        rung(),
        rung({
          concurrency: 2,
          throughput: 120,
          eventLoopDelay: { p50: 0, p95: 0, p99: 1001 },
          completed: 99,
          timeouts: 1
        })
      ])
    ).toMatchObject({ reason: 'event-loop-delay' })
  })

  it('validates suffix rungs even after an earlier saturation', () => {
    expect(() =>
      deriveCapacity([
        rung(),
        rung({ concurrency: 2, throughput: 100 }),
        rung({ concurrency: 1, throughput: Number.NaN, completed: 99 })
      ])
    ).toThrow()
  })

  it('rejects empty, unordered, or incorrectly accounted rungs', () => {
    expect(() => deriveCapacity([])).toThrow()
    expect(() => deriveCapacity([rung({ concurrency: 2 }), rung({ concurrency: 1 })])).toThrow('ordered')
    expect(() => deriveCapacity([rung({ completed: 99 })])).toThrow('accounting')
  })
})

export interface CapacitySettings {
  concurrency: number[]
  minTurns: number
  minWaves: number
  streamDelayMs: number
  asyncPoolSize: number
  turnTimeoutMs: number
}

export interface PercentileSummary {
  p50: number
  p95: number
  p99: number
}

export interface RungSummary {
  concurrency: number
  attempted: number
  completed: number
  errors: number
  timeouts: number
  throughput: number
  infrastructureLatency: PercentileSummary
  eventLoopDelay: PercentileSummary
}

export type SaturationReason = 'infrastructure-latency' | 'throughput-gain' | 'event-loop-delay' | 'errors-or-timeouts'

export type CapacityDerivation =
  | { kind: 'below-range'; saturatedAt: number; reason: SaturationReason }
  | { kind: 'measured'; concurrency: number; saturatedAt: number; reason: SaturationReason }
  | { kind: 'at-least'; concurrency: number }

const DEFAULT_SETTINGS: CapacitySettings = {
  concurrency: [1, 2, 4, 8, 16, 32, 64],
  minTurns: 100,
  minWaves: 4,
  streamDelayMs: 5,
  asyncPoolSize: 16,
  turnTimeoutMs: 30_000
}

function parseInteger(value: string | undefined, key: string, fallback: number, minimum: number): number {
  if (value === undefined) return fallback
  if (!/^(0|[1-9]\d*)$/.test(value)) throw new Error(`${key} must be an integer of at least ${minimum}`)
  const parsed = Number(value)
  if (!Number.isSafeInteger(parsed) || parsed < minimum) {
    throw new Error(`${key} must be a safe integer of at least ${minimum}`)
  }
  return parsed
}

function parseConcurrency(value: string | undefined): number[] {
  if (value === undefined) return [...DEFAULT_SETTINGS.concurrency]
  const tokens = value.split(',').map((token) => token.trim())
  if (tokens.length === 0 || tokens.some((token) => !/^[1-9]\d*$/.test(token))) {
    throw new Error('AC_PG_CAPACITY_CONCURRENCY must contain positive integers')
  }
  const concurrency = tokens.map(Number)
  for (let index = 0; index < concurrency.length; index += 1) {
    const current = concurrency[index]!
    if (!Number.isSafeInteger(current) || (index > 0 && current <= concurrency[index - 1]!)) {
      throw new Error('AC_PG_CAPACITY_CONCURRENCY must be strictly increasing safe integers')
    }
  }
  return concurrency
}

export function parseCapacitySettings(env: Record<string, string | undefined>): CapacitySettings {
  return {
    concurrency: parseConcurrency(env.AC_PG_CAPACITY_CONCURRENCY),
    minTurns: parseInteger(env.AC_PG_CAPACITY_MIN_TURNS, 'AC_PG_CAPACITY_MIN_TURNS', 100, 100),
    minWaves: parseInteger(env.AC_PG_CAPACITY_MIN_WAVES, 'AC_PG_CAPACITY_MIN_WAVES', 4, 4),
    streamDelayMs: parseInteger(env.AC_PG_CAPACITY_STREAM_DELAY_MS, 'AC_PG_CAPACITY_STREAM_DELAY_MS', 5, 0),
    asyncPoolSize: parseInteger(env.AC_PG_CAPACITY_ASYNC_POOL_SIZE, 'AC_PG_CAPACITY_ASYNC_POOL_SIZE', 16, 1),
    turnTimeoutMs: parseInteger(env.AC_PG_CAPACITY_TURN_TIMEOUT_MS, 'AC_PG_CAPACITY_TURN_TIMEOUT_MS', 30_000, 1000)
  }
}

function validateDurations(values: readonly number[]): void {
  if (values.length === 0) throw new Error('durations must not be empty')
  if (values.some((value) => !Number.isFinite(value) || value < 0)) {
    throw new Error('durations must be finite and nonnegative')
  }
}

export function nearestRankPercentile(values: readonly number[], percentile: number): number {
  validateDurations(values)
  if (!Number.isFinite(percentile) || percentile <= 0 || percentile > 100) {
    throw new Error('percentile must be finite and in (0, 100]')
  }
  const sorted = [...values].sort((left, right) => left - right)
  return sorted[Math.ceil((percentile / 100) * sorted.length) - 1]!
}

export function summarizeDurations(values: readonly number[]): PercentileSummary {
  return {
    p50: nearestRankPercentile(values, 50),
    p95: nearestRankPercentile(values, 95),
    p99: nearestRankPercentile(values, 99)
  }
}

export interface EventLoopDriftSamplerSeams<Timer = unknown> {
  now: () => number
  setInterval: (callback: () => void, delayMs: number) => Timer
  clearInterval: (timer: Timer) => void
}

export interface EventLoopDriftSampler {
  samples: readonly number[]
  stop(): readonly number[]
}

function createEventLoopDriftSamplerWithSeams<Timer>(seams: EventLoopDriftSamplerSeams<Timer>): EventLoopDriftSampler {
  const intervalMs = 10
  const samples: number[] = []
  let previousActual = seams.now()
  let stopped = false
  const sample = () => {
    const actual = seams.now()
    samples.push(Math.max(0, actual - previousActual - intervalMs))
    previousActual = actual
  }
  const timer = seams.setInterval(sample, intervalMs)
  return {
    get samples() {
      return samples
    },
    stop() {
      if (!stopped) {
        stopped = true
        sample()
        seams.clearInterval(timer)
      }
      return samples
    }
  }
}

export function createEventLoopDriftSampler<Timer>(seams?: EventLoopDriftSamplerSeams<Timer>): EventLoopDriftSampler {
  if (seams) return createEventLoopDriftSamplerWithSeams(seams)
  return createEventLoopDriftSamplerWithSeams({
    now: performance.now.bind(performance),
    setInterval,
    clearInterval
  })
}

export interface TimeoutSeams<Timer = unknown> {
  now: () => number
  setTimeout: (callback: () => void, delayMs: number) => Timer
  clearTimeout: (timer: Timer) => void
}

export type MeasurementOutcome<T> =
  | { status: 'completed'; elapsedMs: number; value: T }
  | { status: 'error'; elapsedMs: number; error: unknown }
  | { status: 'timeout'; elapsedMs: number }

type SettledOperation<T> =
  { status: 'completed'; value: T } | { status: 'error'; error: unknown } | { status: 'timer-timeout' }

async function measureWithTimeoutUsingSeams<T, Timer>(
  operation: () => Promise<T> | T,
  timeoutMs: number,
  seams: TimeoutSeams<Timer>
): Promise<MeasurementOutcome<T>> {
  if (!Number.isFinite(timeoutMs) || timeoutMs < 0) throw new Error('timeoutMs must be finite and nonnegative')
  const startedAt = seams.now()
  const settledOperation: Promise<SettledOperation<T>> = Promise.resolve()
    .then(operation)
    .then(
      (value) => ({ status: 'completed', value }),
      (error: unknown) => ({ status: 'error', error })
    )
  let timer!: Timer
  const timerTimeout = new Promise<SettledOperation<T>>((resolve) => {
    timer = seams.setTimeout(() => resolve({ status: 'timer-timeout' }), timeoutMs)
  })
  const settled = await Promise.race([settledOperation, timerTimeout])
  seams.clearTimeout(timer)
  const elapsedMs = Math.max(0, seams.now() - startedAt)
  if (settled.status === 'timer-timeout' || elapsedMs >= timeoutMs) return { status: 'timeout', elapsedMs }
  if (settled.status === 'error') return { status: 'error', elapsedMs, error: settled.error }
  return { status: 'completed', elapsedMs, value: settled.value }
}

export function measureWithTimeout<T, Timer>(
  operation: () => Promise<T> | T,
  timeoutMs: number,
  seams?: TimeoutSeams<Timer>
): Promise<MeasurementOutcome<T>> {
  if (seams) return measureWithTimeoutUsingSeams(operation, timeoutMs, seams)
  return measureWithTimeoutUsingSeams(operation, timeoutMs, {
    now: performance.now.bind(performance),
    setTimeout,
    clearTimeout
  })
}

function validateCount(value: number, name: string): void {
  if (!Number.isSafeInteger(value) || value < 0) throw new Error(`${name} must be a nonnegative safe integer`)
}

export function validateRungAccounting(rung: RungSummary): void {
  validateCount(rung.attempted, 'attempted')
  validateCount(rung.completed, 'completed')
  validateCount(rung.errors, 'errors')
  validateCount(rung.timeouts, 'timeouts')
  if (rung.completed + rung.errors + rung.timeouts !== rung.attempted) {
    throw new Error('rung accounting must satisfy completed + errors + timeouts === attempted')
  }
}

function validateMetric(value: number, name: string): void {
  if (!Number.isFinite(value) || value < 0) throw new Error(`${name} must be finite and nonnegative`)
}

function saturationReason(
  rung: RungSummary,
  previous: RungSummary | undefined,
  baselineLatencyP95: number
): SaturationReason | undefined {
  if (rung.infrastructureLatency.p95 > baselineLatencyP95 * 2) return 'infrastructure-latency'
  if (previous) {
    const gain =
      previous.throughput === 0
        ? rung.throughput === 0
          ? 0
          : Number.POSITIVE_INFINITY
        : (rung.throughput - previous.throughput) / previous.throughput
    if (gain < 0.2) return 'throughput-gain'
  }
  if (rung.eventLoopDelay.p99 > 1000) return 'event-loop-delay'
  if (rung.errors > 0 || rung.timeouts > 0) return 'errors-or-timeouts'
  return undefined
}

export function deriveCapacity(rungs: readonly RungSummary[]): CapacityDerivation {
  if (rungs.length === 0) throw new Error('at least one rung is required')
  for (let index = 0; index < rungs.length; index += 1) {
    const rung = rungs[index]!
    validateRungAccounting(rung)
    validateCount(rung.concurrency, 'concurrency')
    if (rung.concurrency === 0 || (index > 0 && rung.concurrency <= rungs[index - 1]!.concurrency)) {
      throw new Error('rungs must be ordered by strictly increasing positive concurrency')
    }
    validateMetric(rung.throughput, 'throughput')
    for (const [name, summary] of [
      ['infrastructureLatency', rung.infrastructureLatency],
      ['eventLoopDelay', rung.eventLoopDelay]
    ] as const) {
      validateMetric(summary.p50, `${name}.p50`)
      validateMetric(summary.p95, `${name}.p95`)
      validateMetric(summary.p99, `${name}.p99`)
      if (summary.p50 > summary.p95 || summary.p95 > summary.p99) throw new Error(`${name} percentiles must be ordered`)
    }
  }

  const baselineLatencyP95 = rungs[0]!.infrastructureLatency.p95
  for (let index = 0; index < rungs.length; index += 1) {
    const rung = rungs[index]!
    const reason = saturationReason(rung, rungs[index - 1], baselineLatencyP95)
    if (!reason) continue
    if (index === 0) return { kind: 'below-range', saturatedAt: rung.concurrency, reason }
    return { kind: 'measured', concurrency: rungs[index - 1]!.concurrency, saturatedAt: rung.concurrency, reason }
  }
  return { kind: 'at-least', concurrency: rungs.at(-1)!.concurrency }
}

import { describe, expect, it } from 'vitest'
