const AUTHOR = 'agent-author'
const PEER = 'agent-peer'

function claim(overrides: Record<string, unknown> = {}) {
  return {
    metadata: {
      event_type: AGENTCONNECT_THREAD_EVENT_TYPE,
      event_payload: {
        author_agent_id: AUTHOR,
        response_id: 'r-1',
        delivery_state: 'final',
        hop_count: 2,
        mentioned_agent_ids: [PEER],
        ...overrides
      }
    }
  }
}

describe('readAgentAuthorshipClaim (§4/§8.1)', () => {
  it('reads a complete claim', () => {
    expect(readAgentAuthorshipClaim(claim())).toEqual({
      authorAgentId: AUTHOR,
      responseId: 'r-1',
      deliveryState: 'final',
      hopCount: 2,
      mentionedAgentIds: [PEER]
    })
  })

  it('round-trips `addressed anyone` from the complete reply text through the claim', () => {
    // The whole producer → metadata → parser path for the one fact the final event cannot
    // otherwise carry (§2.3/§5.5): only the LAST section is marked final, so a mention the
    // splitter left in an earlier section exists nowhere else by the time this is read.
    const wholeReply = '<@UHUMAN> here is the summary.\n\n…and this is the tail section.'
    const tailSection = '…and this is the tail section.'

    // The producer reads the COMPLETE reply; the tail on its own addresses nobody, which
    // is exactly why the author has to state it.
    expect(slackTextAddressesAnyone(wholeReply)).toBe(true)
    expect(slackTextAddressesAnyone(tailSection)).toBe(false)

    expect(readAgentAuthorshipClaim(claim({ addressed_anyone: true }))?.addressedAnyone).toBe(true)

    // Absent ⇒ omitted, not `false`: an older author cannot report it, and its finals must
    // stay routable exactly as before. A non-boolean is not an assertion either, so a
    // malformed value degrades to "named nobody" rather than blocking every continuation.
    expect(readAgentAuthorshipClaim(claim())).not.toHaveProperty('addressedAnyone')
    expect(readAgentAuthorshipClaim(claim({ addressed_anyone: 'yes' }))).not.toHaveProperty('addressedAnyone')
    expect(readAgentAuthorshipClaim(claim({ addressed_anyone: false }))).not.toHaveProperty('addressedAnyone')
  })

  it('matches every mention form `mentionedBots` is built from', () => {
    // The producer and the reader must agree on what counts as an address, so this uses
    // the same pattern rather than a second opinion about it.
    expect(slackTextAddressesAnyone('plain prose with no address')).toBe(false)
    expect(slackTextAddressesAnyone('<@U012ABC> please look')).toBe(true)
    expect(slackTextAddressesAnyone('trailing address <@W99XYZ>')).toBe(true)
    // Stateful `/g` regexes give alternating answers when reused; this must not.
    expect(slackTextAddressesAnyone('<@U012ABC> one')).toBe(true)
    expect(slackTextAddressesAnyone('<@U012ABC> two')).toBe(true)
  })

  it('carries the paired agent-call delivery id when present', () => {
    expect(readAgentAuthorshipClaim(claim({ agent_call_delivery_id: 'd-9' }))?.agentCallDeliveryId).toBe('d-9')
  })

  it('ignores chrome and foreign metadata', () => {
    expect(
      readAgentAuthorshipClaim({ metadata: { event_type: 'agentconnect_chrome', event_payload: {} } })
    ).toBeUndefined()
    expect(readAgentAuthorshipClaim({})).toBeUndefined()
  })

  it('drops the WHOLE claim when hop depth is missing or unusable', () => {
    // §4.1: an unverifiable source depth is transcript-only. Defaulting it to 0 would
    // silently hand a runaway A→B→A chain a fresh loop-protection budget every hop, so a
    // partial claim must not survive as a half-read object.
    for (const hop_count of [undefined, -1, 1.5, '2', null]) {
      expect(readAgentAuthorshipClaim(claim({ hop_count }))).toBeUndefined()
    }
  })

  it('drops a claim with no author, no response id, or an unknown lifecycle state', () => {
    expect(readAgentAuthorshipClaim(claim({ author_agent_id: '  ' }))).toBeUndefined()
    expect(readAgentAuthorshipClaim(claim({ response_id: undefined }))).toBeUndefined()
    expect(readAgentAuthorshipClaim(claim({ delivery_state: 'done' }))).toBeUndefined()
    expect(readAgentAuthorshipClaim(claim({ mentioned_agent_ids: 'peer' }))).toBeUndefined()
  })

  it('rides along on an ordinary normalized message, untrusted', () => {
    const normalized = normalizeSlackMessage({
      type: 'message',
      channel: 'C1',
      ts: '1720000000.000100',
      bot_id: 'B1',
      app_id: 'A1',
      text: `<@U09SHARED> reviewer take a look`,
      ...claim({ delivery_state: 'streaming' })
    })
    expect(normalized?.agentAuthorship?.deliveryState).toBe('streaming')
    expect(normalized?.agentAuthorship?.authorAgentId).toBe(AUTHOR)
  })
})

describe('normalizeSlackResponseFinalization (§5)', () => {
  const wrapper = (nested: Record<string, unknown>) => ({
    type: 'message',
    subtype: 'message_changed' as const,
    channel: 'C1',
    ts: '1720000000.000999',
    message: {
      type: 'message',
      ts: '1720000000.000100',
      thread_ts: '1720000000.000001',
      bot_id: 'B1',
      app_id: 'A1',
      text: '<@U01PEER> please verify the rollout',
      ...nested
    }
  })

  it('unwraps the closing edit onto the ORIGINAL message identity', () => {
    const msg = normalizeSlackResponseFinalization(wrapper(claim()))
    expect(msg).not.toBeNull()
    // Channel comes from the wrapper; ts/thread/text/sender from the edited message —
    // normalizing the wrapper itself would produce an anonymous empty message.
    expect(msg!.channel).toBe('C1')
    expect(msg!.thread).toBe('1720000000.000001')
    expect(msg!.text).toBe('<@U01PEER> please verify the rollout')
    expect(msg!.sender.appId).toBe('A1')
    expect(msg!.agentAuthorship?.mentionedAgentIds).toEqual([PEER])
  })

  it('separates the finalization from its post by TAG, keeping the msgId identical', () => {
    // The streaming post and its closing edit describe one Slack message and share a
    // `ts`; only the SECOND carries the recipient set, so ingress dedup must not collapse
    // them. The distinction belongs in `ingressEventTag`, NOT in `msgId`: `msgId` also
    // carries the platform ts, and the transcript uses that ts as both its uniqueness key
    // and its ordering key. A `:final` msgId suffix made every finalization in a thread
    // collapse onto the literal ts `'final'` — one row survived and it sorted to epoch 0.
    const streaming = normalizeSlackMessage({
      type: 'message',
      channel: 'C1',
      ts: '1720000000.000100',
      bot_id: 'B1',
      text: 'partial',
      ...claim({ delivery_state: 'streaming' })
    })
    const final = normalizeSlackResponseFinalization(wrapper(claim()))
    expect(final!.msgId).toBe(streaming!.msgId)
    expect(final!.ingressEventTag).toBe(SLACK_RESPONSE_FINAL_EVENT_TAG)
    expect(streaming!.ingressEventTag).toBeUndefined()
    // The ts must stay recoverable by the ordinary split every consumer performs.
    expect(final!.msgId.split(':')[2]).toBe('1720000000.000100')
  })

  it('drops the wrapper subtype so later stages see an ordinary post', () => {
    // Leaving `message_changed` attached would make every downstream routability check
    // reject the very event this path exists to admit.
    const msg = normalizeSlackResponseFinalization(wrapper(claim()))
    expect((msg as unknown as { subtype?: string }).subtype).toBeUndefined()
  })

  it('returns null for a mid-answer streaming edit', () => {
    // §5.4: intermediate edits must never enter routing — their text may be a prefix.
    expect(normalizeSlackResponseFinalization(wrapper(claim({ delivery_state: 'streaming' })))).toBeNull()
  })

  it('returns null for an ordinary human edit and for non-edit events', () => {
    expect(normalizeSlackResponseFinalization(wrapper({ user: 'U1', metadata: undefined }))).toBeNull()
    expect(
      normalizeSlackResponseFinalization({ type: 'message', channel: 'C1', ts: '1', text: 'hi', ...claim() })
    ).toBeNull()
  })

  it('returns null for a chrome edit', () => {
    // Status bars and cards are edited constantly; none of them is a response event.
    expect(
      normalizeSlackResponseFinalization(
        wrapper({ metadata: { event_type: 'agentconnect_chrome', event_payload: {} } })
      )
    ).toBeNull()
  })
})

import { afterEach, describe, expect, it } from 'vitest'
import { lstatSync, mkdirSync, mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { prepareMicrosandboxLaunch } from '../src/microsandbox/launch.js'
import { prepareClaudeApiSecret } from '../src/microsandbox/native-api-secrets.js'
import { fifoWriter, killFifoWriters, mkfifo, statsBeforeSwap } from './fifo-support.js'

const roots: string[] = []
const key = 'fixture-native-api-key'
function write(path: string, data: unknown) {
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, typeof data === 'string' ? data : JSON.stringify(data))
}

function fixture(runtimeId: 'claude-acp' | 'codex-acp') {
  const root = mkdtempSync(join(tmpdir(), 'ac-native-api-'))
  roots.push(root)
  const hostHome = join(root, 'host')
  const scopeDir = join(root, 'agent')
  const cwd = join(scopeDir, 'workspace')
  mkdirSync(cwd, { recursive: true })
  mkdirSync(hostHome)
  return {
    root,
    hostHome,
    runtimeId,
    runtime: { command: runtimeId === 'claude-acp' ? 'claude-agent-acp' : 'codex-acp', args: [], env: [] },
    scopeDir,
    cwd,
    mounts: [],
    stateSourceEnv: { HOME: hostHome }
  }
}

afterEach(() => {
  killFifoWriters()
  for (const root of roots.splice(0)) rmSync(root, { recursive: true, force: true })
})

it.skipIf(process.platform === 'win32')(
  'refuses a Claude global config swapped for a FIFO after its stat instead of protecting what it sends',
  () => {
    const { hostHome } = fixture('claude-acp')
    mkdirSync(join(hostHome, '.claude'))
    const regular = join(hostHome, 'regular.json')
    writeFileSync(regular, '{}')
    // A runtime-created `.config.json` in the shared config dir becomes the global config.
    const legacy = join(hostHome, '.claude', '.config.json')
    mkfifo(legacy)
    fifoWriter(legacy, JSON.stringify({ primaryApiKey: 'synthetic-planted' }))
    const restore = statsBeforeSwap([legacy], regular)
    try {
      expect(() => prepareClaudeApiSecret({ HOME: hostHome }, {})).toThrow(
        /Cannot read the host runtime API credential/
      )
    } finally {
      restore()
    }
  }
)

describe.skipIf(process.platform !== 'linux')('microsandbox native file API credentials', () => {
  it.each(['default', 'relocated', 'legacy'])(
    'protects Claude %s login without changing native auth precedence',
    (layout) => {
      const opts = fixture('claude-acp')
      const configDir = join(opts.hostHome, layout === 'default' ? '.claude' : 'configured-claude')
      const source =
        layout === 'default'
          ? join(opts.hostHome, '.claude.json')
          : join(configDir, layout === 'legacy' ? '.config.json' : '.claude.json')
      const stateSourceEnv = {
        ...opts.stateSourceEnv,
        CODEX_CA_CERTIFICATE: '/tmp/codex-only-ca.pem',
        ...(layout === 'default' ? {} : { CLAUDE_CONFIG_DIR: configDir })
      }
      const host = {
        primaryApiKey: key,
        additionalModelOptionsCache: { model: 'fixture-model' },
        projects: { private: {} }
      }
      write(source, host)
      const launchOpts = { ...opts, stateSourceEnv }
      const launch = prepareMicrosandboxLaunch(launchOpts)
      const secret = launch.microsandbox.secrets![0]!
      expect(secret.host).toEqual(['api.anthropic.com'])
      expect(secret.readValue()).toBe(key)
      expect(launch.env.ANTHROPIC_API_KEY).toBeUndefined()
      expect(launch.env.CLAUDE_CODE_OAUTH_TOKEN).toBeUndefined()
      expect(JSON.stringify(launch)).not.toContain(key)
      expect(launch.microsandbox.mounts.some(({ source }) => source === configDir)).toBe(false)
      const path = join(launch.runtimeHome!, '.claude', layout === 'legacy' ? '.config.json' : '.claude.json')
      const projected = JSON.parse(readFileSync(path, 'utf8'))
      expect(projected).toEqual({
        primaryApiKey: secret.placeholder,
        additionalModelOptionsCache: host.additionalModelOptionsCache
      })
      expect(launch.toolSandbox!.protectedCredentialRoots).toContain(join(launch.runtimeHome!, '.claude'))
      projected.projects = { workspace: { approved: true } }
      write(path, projected)
      write(source, { ...host, primaryApiKey: 'fixture-rotated-key' })
      const resumed = prepareMicrosandboxLaunch(launchOpts)
      expect(resumed.microsandbox.secrets![0]!.readValue()).toBe('fixture-rotated-key')
      expect(JSON.parse(readFileSync(path, 'utf8'))).toEqual(projected)
      expect(JSON.parse(readFileSync(source, 'utf8')).primaryApiKey).toBe('fixture-rotated-key')
      expect(() => prepareMicrosandboxLaunch({ ...launchOpts, trustedRuntimeReadRoots: [source] })).toThrow(
        'protected host credential'
      )
    }
  )

  it('keeps Claude OAuth shared while projecting a separate saved API key', () => {
    const opts = fixture('claude-acp')
    const credentialDir = join(opts.hostHome, '.claude')
    const oauth = { claudeAiOauth: { accessToken: 'fixture-oauth', refreshToken: 'fixture-refresh', expiresAt: 1 } }
    write(join(credentialDir, '.credentials.json'), oauth)
    write(join(opts.hostHome, '.claude.json'), { primaryApiKey: key })
    const launch = prepareMicrosandboxLaunch(opts)
    expect(launch.env.CLAUDE_SECURESTORAGE_CONFIG_DIR).toBe(credentialDir)
    expect(launch.microsandbox.mounts).toContainEqual({
      source: credentialDir,
      target: credentialDir,
      mode: 'writable'
    })
    expect(JSON.parse(readFileSync(join(credentialDir, '.credentials.json'), 'utf8'))).toEqual(oauth)
    const source = join(credentialDir, '.config.json')
    write(source, { primaryApiKey: key })
    expect(() => prepareMicrosandboxLaunch(opts)).toThrow('protected host credential source')
  })

  it('replaces Codex auth mounts with private placeholders and preserves config and key rotation', () => {
    const opts = fixture('codex-acp')
    const auth = join(opts.hostHome, '.codex', 'auth.json')
    const config = join(opts.hostHome, '.codex', 'config.toml')
    write(auth, { auth_mode: 'apikey', OPENAI_API_KEY: key, tokens: null })
    write(
      config,
      `model = "fixture-model"\nopenai_base_url = "https://gateway.example.test/v1"\n[model_providers.other.http_headers]\nx-api-key = "${key}"\n`
    )
    const launch = prepareMicrosandboxLaunch(opts)
    const secret = launch.microsandbox.secrets![0]!
    expect(secret.host).toEqual(['gateway.example.test'])
    expect(launch.env.OPENAI_API_KEY).toBeUndefined()
    expect(launch.env.CODEX_API_KEY).toBeUndefined()
    expect(JSON.stringify(launch)).not.toContain(key)
    expect(launch.microsandbox.mounts.some(({ source }) => source === auth)).toBe(false)
    const path = join(launch.runtimeHome!, '.codex', 'auth.json')
    expect(lstatSync(path).isSymbolicLink()).toBe(false)
    expect(JSON.parse(readFileSync(path, 'utf8'))).toEqual({
      auth_mode: 'apikey',
      OPENAI_API_KEY: secret.placeholder,
      tokens: null
    })
    expect(readFileSync(join(launch.runtimeHome!, '.codex', 'config.toml'), 'utf8')).not.toContain(key)
    expect(launch.toolSandbox!.protectedCredentialRoots).toContain(join(launch.runtimeHome!, '.codex'))
    write(auth, { auth_mode: 'apikey', OPENAI_API_KEY: 'fixture-rotated-key' })
    expect(prepareMicrosandboxLaunch(opts).microsandbox.secrets![0]!.readValue()).toBe('fixture-rotated-key')
    expect(JSON.parse(readFileSync(path, 'utf8')).OPENAI_API_KEY).toBe(secret.placeholder)
    expect(() =>
      prepareMicrosandboxLaunch({ ...opts, mounts: [{ source: auth, target: '/tmp/auth-alias', mode: 'readonly' }] })
    ).toThrow('protected host')
    write(auth, { auth_mode: 'chatgpt', OPENAI_API_KEY: key, tokens: { access_token: 'fixture-oauth' } })
    expect(() => prepareMicrosandboxLaunch(opts)).toThrow('combined API key and non-API authentication')
  })

  it('resolves Codex file logins and provider profiles without treating OPENAI_BASE_URL as routing', () => {
    const opts = fixture('codex-acp')
    const configDir = join(opts.hostHome, 'configured-codex')
    const auth = join(configDir, 'auth.json')
    const actual = join(opts.hostHome, 'managed-auth.json')
    write(actual, { OPENAI_API_KEY: key })
    mkdirSync(configDir)
    symlinkSync(actual, auth)
    write(
      join(configDir, 'config.toml'),
      'profile="fixture"\n[profiles.fixture]\nmodel_provider="custom"\n[model_providers.custom]\nbase_url="https://custom.example.test/v1"\nrequires_openai_auth=true\n'
    )
    const launchOpts = {
      ...opts,
      stateSourceEnv: { ...opts.stateSourceEnv, CODEX_HOME: configDir, OPENAI_BASE_URL: 'https://unused.example.test' }
    }
    const launch = prepareMicrosandboxLaunch(launchOpts)
    expect(launch.microsandbox.secrets![0]!.host).toEqual(['custom.example.test'])
    expect(JSON.parse(readFileSync(join(launch.runtimeHome!, '.codex', 'auth.json'), 'utf8')).OPENAI_API_KEY).toMatch(
      /^msb-secret-/
    )
    const override = prepareMicrosandboxLaunch({
      ...launchOpts,
      explicitEnv: {
        CODEX_CONFIG: JSON.stringify({ model_provider: 'openai', openai_base_url: 'https://override.example.test/v1' })
      }
    })
    expect(override.microsandbox.secrets![0]!.host).toEqual(['override.example.test'])
    expect(() =>
      prepareMicrosandboxLaunch({ ...launchOpts, explicitEnv: { CODEX_CA_CERTIFICATE: '/tmp/custom-ca.pem' } })
    ).toThrow('custom TLS trust')
  })

  it.each(['claude-acp', 'codex-acp'] as const)(
    'withholds %s API keys from unsupported HTTP endpoints',
    (runtimeId) => {
      const opts = fixture(runtimeId)
      const claude = runtimeId === 'claude-acp'
      const source = join(opts.hostHome, claude ? '.claude.json' : '.codex/auth.json')
      write(source, claude ? { primaryApiKey: key } : { OPENAI_API_KEY: key })
      const base = 'http://localhost:8080/v1'
      const launch = prepareMicrosandboxLaunch({
        ...opts,
        explicitEnv: claude ? { ANTHROPIC_BASE_URL: base } : { CODEX_CONFIG: JSON.stringify({ openai_base_url: base }) }
      })
      expect(launch.microsandbox.secrets).toEqual([])
      const text = readFileSync(join(launch.runtimeHome!, claude ? '.claude/.claude.json' : '.codex/auth.json'), 'utf8')
      expect(text).not.toContain(key)
      expect(text).toContain('msb-secret-')
      expect(launch.env.NODE_EXTRA_CA_CERTS).toBeUndefined()
    }
  )
})

import { describe, expect, it } from 'vitest'
import { normalizeSlackMessage, type SlackMessage } from '../src/slack-message.js'

/**
 * The search credential must not survive normalization.
 *
 * Slack's `action_token` is the only thing that lets a BOT token search the workspace, and it
 * arrives on the ordinary message event. The normalized message is not a safe place for it:
 * the owning daemon persists that object to its durable inbox and replays it after a restart,
 * and the relay forwards it as `rd/msg` `payload`. So ingress lifts the token into memory and
 * normalization drops it — this test is what keeps that true.
 *
 * The guard is structural rather than field-by-field: any future normalizer that copies the
 * raw event wholesale would carry the token along, and a whole-object scan catches that where
 * an assertion on one property name would not.
 */
const event = (over: Partial<SlackMessage> = {}): SlackMessage => ({
  type: 'message',
  channel: 'C1',
  ts: '1700000000.000100',
  user: 'U1',
  text: 'what did we decide about the rollout?',
  action_token: 'xoxa-super-secret',
  ...over
})

describe('Slack search credential', () => {
  it('never appears in the normalized message, at any depth', () => {
    const normalized = normalizeSlackMessage(event())
    expect(normalized).toBeTruthy()
    const serialized = JSON.stringify(normalized)
    expect(serialized).not.toContain('xoxa-super-secret')
    expect(serialized).not.toContain('action_token')
  })

  it('does not otherwise change how the message normalizes', () => {
    const withToken = normalizeSlackMessage(event())
    const without = normalizeSlackMessage(event({ action_token: undefined }))
    expect(withToken).toEqual(without)
  })
})

import { describe, expect, it } from 'vitest'
import { createHash, randomUUID } from 'node:crypto'
import type { MemoryTransactionCommit, MemoryTransactionResult } from '@agentconnect.md/protocol'
import { prisma } from '../setup.db.js'
import { DEF_ORG, seedAgent, seedDaemon } from '../fixtures/seed.js'
import { systemClock } from '../../src/domain/clock.js'
import { AgentId } from '../../src/domain/ids.js'
import {
  PgAgentMemoryFileRepo,
  PgAgentMemoryHistoryRepo
} from '../../src/persistence/repositories/agent-memory.repo.js'
import { PgAgentMemoryTransactionRepo } from '../../src/persistence/repositories/agent-memory-transaction.repo.js'
import { AgentMemoryTransactionService } from '../../src/agent-memory/transaction.service.js'

const NOW = new Date('2026-09-09T13:00:00Z')
const hash = (value: string) => createHash('sha256').update(value).digest('hex')
async function fixture() {
  const daemonId = randomUUID()
  await seedDaemon(prisma, daemonId)
  const agentId = AgentId(randomUUID())
  await seedAgent(prisma, agentId, {
    daemonId,
    runtimeOverrides: { memory: { provider: 'managed', home: 'control-plane' } }
  })
  const files = new PgAgentMemoryFileRepo(prisma)
  const repo = new PgAgentMemoryTransactionRepo(prisma)
  const service = new AgentMemoryTransactionService(repo, {
    now: () => NOW.getTime(),
    setTimeout: systemClock.setTimeout.bind(systemClock),
    clearTimeout: systemClock.clearTimeout.bind(systemClock)
  })
  const apply = (req: Parameters<typeof service.apply>[1]) => service.apply({ id: agentId, orgId: DEF_ORG }, req)
  const snapshot = async () => {
    const result = await apply({ agentId, root: 'memory', operation: 'snapshot' })
    if (result.operation !== 'snapshot') throw new Error(JSON.stringify(result))
    return result.revision
  }
  const stage = async (path: string, text: string, expectedRevision: string | null = null) => {
    const temp = `.agentconnect-memory-${randomUUID()}.tmp`
    await files.append(agentId, DEF_ORG, `memory/${temp}`, Buffer.from(text), true, NOW)
    return { action: 'put' as const, path, temp, stagedRevision: hash(text), expectedRevision }
  }
  const request = async (changes: MemoryTransactionCommit['changes']): Promise<MemoryTransactionCommit> => ({
    operation: 'commit',
    agentId,
    root: 'memory',
    operationId: randomUUID(),
    expectedRevision: await snapshot(),
    source: 'console',
    changes
  })
  const read = async (path: string) => {
    const row = await files.read(agentId, `memory/${path}`, 0, 256000)
    return row ? Buffer.from(row.slice).toString('utf8') : null
  }
  return { agentId, apply, snapshot, stage, request, read, files }
}
function receipt(result: MemoryTransactionResult) {
  if (result.operation !== 'commit') throw new Error(JSON.stringify(result))
  return result.receipt
}

describe('atomic memory home publication', () => {
  it('publishes topic, index, history and receipt together, with no staging rows left', async () => {
    const f = await fixture()
    const req = await f.request([await f.stage('topic.md', 'hello'), await f.stage('MEMORY.md', '[topic](topic.md)')])
    const done = receipt(await f.apply(req))
    expect(await f.read('topic.md')).toBe('hello')
    expect(await f.read('MEMORY.md')).toBe('[topic](topic.md)')
    expect(done.revision).toBe(await f.snapshot())
    expect(await prisma.agentMemoryFile.count({ where: { agentId: f.agentId, stagedAt: { not: null } } })).toBe(0)
    const history = await prisma.agentMemoryHistory.findMany({ where: { agentId: f.agentId } })
    expect(history.map((row) => row.path).sort()).toEqual(['MEMORY.md', 'topic.md'])
    expect(history.every((row) => row.source === 'console')).toBe(true)
    const ledger = await prisma.agentMemoryMutation.findMany({ where: { agentId: f.agentId } })
    expect(ledger).toHaveLength(1)
    expect(ledger[0]!.receipt).toEqual(done)
    expect(JSON.stringify(ledger)).not.toContain('hello')
  })

  it('allows one competing snapshot commit and never combines independently prepared indexes', async () => {
    const f = await fixture()
    const a = await f.request([await f.stage('a.md', 'a'), await f.stage('MEMORY.md', 'index-a')])
    const b = await f.request([await f.stage('b.md', 'b'), await f.stage('MEMORY.md', 'index-b')])
    const results = await Promise.all([f.apply(a), f.apply(b)])
    expect(results.filter((result) => result.operation === 'commit')).toHaveLength(1)
    expect(results.filter((result) => result.operation === 'error')).toEqual([
      { operation: 'error', code: 'CONFLICT', message: 'memory tree changed while the mutation was prepared' }
    ])
    const winner = results[0]!.operation === 'commit' ? 'a' : 'b'
    expect(await f.read('MEMORY.md')).toBe(`index-${winner}`)
    expect(await f.read(`${winner}.md`)).toBe(winner)
    expect(await f.read(`${winner === 'a' ? 'b' : 'a'}.md`)).toBeNull()
  })

  it('replays the identical operation across repo instances even after history is removed', async () => {
    const f = await fixture()
    const req = await f.request([await f.stage('topic.md', '')])
    const results = await Promise.all([
      f.apply(req),
      new PgAgentMemoryTransactionRepo(prisma).apply(f.agentId, DEF_ORG, req, NOW)
    ])
    expect(results.map((result) => result.operation === 'commit' && result.replayed).sort()).toEqual([false, true])
    expect(receipt(results[0]!)).toEqual(receipt(results[1]!))
    await new PgAgentMemoryHistoryRepo(prisma).deleteTree(f.agentId)
    expect(receipt(await f.apply(req))).toEqual(receipt(results[0]!))
    expect(await f.read('topic.md')).toBe('')
    expect(await prisma.agentMemoryHistory.count({ where: { agentId: f.agentId } })).toBe(0)
    expect(await f.apply({ ...req, source: 'tool' })).toMatchObject({ operation: 'error', code: 'CONFLICT' })
  })

  it('rejects stale targets, changed staging and legacy mutations without partial publication', async () => {
    const f = await fixture()
    const a = await f.stage('a.md', 'a')
    const b = await f.stage('b.md', 'b')
    const req = await f.request([a, { ...b, stagedRevision: hash('wrong') }])
    expect(await f.apply(req)).toMatchObject({ operation: 'error', code: 'CONFLICT' })
    expect(await f.read('a.md')).toBeNull()
    expect(await prisma.agentMemoryHistory.count({ where: { agentId: f.agentId } })).toBe(0)
    const valid = { ...req, changes: [a, b] }
    const other = await f.stage('legacy.md', 'legacy')
    await f.files.commit(f.agentId, 'memory/legacy.md', `memory/${other.temp}`, undefined, NOW)
    expect(await f.apply(valid)).toMatchObject({ operation: 'error', code: 'CONFLICT' })
    const fresh = await f.request([{ ...a, expectedRevision: hash('absent') }])
    expect(await f.apply(fresh)).toMatchObject({ operation: 'error', code: 'CONFLICT' })
  })

  it('rolls back file and staging changes if history insertion fails', async () => {
    const f = await fixture()
    const req = await f.request([await f.stage('topic.md', 'new'), await f.stage('MEMORY.md', 'index')])
    await prisma.$executeRawUnsafe(
      `ALTER TABLE agent_memory_history ADD CONSTRAINT memory_test_history_failure CHECK (source <> 'console')`
    )
    try {
      await expect(f.apply(req)).rejects.toThrow()
      expect(await f.read('topic.md')).toBeNull()
      expect(await f.read('MEMORY.md')).toBeNull()
      expect(await prisma.agentMemoryMutation.count({ where: { agentId: f.agentId } })).toBe(0)
      expect(await prisma.agentMemoryFile.count({ where: { agentId: f.agentId, stagedAt: { not: null } } })).toBe(2)
    } finally {
      await prisma.$executeRawUnsafe('ALTER TABLE agent_memory_history DROP CONSTRAINT memory_test_history_failure')
    }
    expect((await f.apply(req)).operation).toBe('commit')
  })

  it('atomically deletes a topic and updates its index, preserving deletion provenance', async () => {
    const f = await fixture()
    receipt(await f.apply(await f.request([await f.stage('topic.md', 'old'), await f.stage('MEMORY.md', 'old index')])))
    const done = await f.apply(
      await f.request([
        { action: 'delete', path: 'topic.md', expectedRevision: hash('old') },
        await f.stage('MEMORY.md', '', hash('old index'))
      ])
    )
    expect(receipt(done).files[0]).toEqual({ path: 'topic.md', revision: null, mtime: null })
    expect(await f.read('topic.md')).toBeNull()
    expect(await f.read('MEMORY.md')).toBe('')
    expect(await prisma.agentMemoryHistory.findFirst({ where: { agentId: f.agentId, event: 'delete' } })).toMatchObject(
      { before: 'old', after: '', source: 'console' }
    )
  })

  it('refuses escaped roots and a binding that moved away from the CP home', async () => {
    const f = await fixture()
    expect(await f.apply({ agentId: f.agentId, root: '../memory', operation: 'snapshot' })).toMatchObject({
      operation: 'error',
      code: 'INVALID_ARGUMENT'
    })
    const req = await f.request([await f.stage('topic.md', 'new')])
    await prisma.agent.update({
      where: { id: f.agentId },
      data: { runtimeOverrides: { memory: { provider: 'managed', home: 'daemon' } } }
    })
    expect(await f.apply(req)).toMatchObject({ operation: 'error', code: 'FORBIDDEN' })
    expect(await f.read('topic.md')).toBeNull()
  })
  it('suppresses delayed capture after a completed explicit mutation, across repo instances and history retention', async () => {
    const f = await fixture()
    const sourceTurnId = randomUUID()
    const explicit = { ...(await f.request([await f.stage('topic.md', 'correction')])), sourceTurnId }
    receipt(await f.apply(explicit))
    await prisma.agentMemoryHistory.deleteMany({ where: { agentId: f.agentId } })
    const restarted = new PgAgentMemoryTransactionRepo(prisma)
    expect(
      await restarted.apply(
        f.agentId,
        DEF_ORG,
        { operation: 'capture-status', agentId: f.agentId, root: 'memory', sourceTurnId },
        NOW
      )
    ).toEqual({ operation: 'capture-status', suppressed: true })
    const delayed = {
      ...(await f.request([await f.stage('topic.md', 'old extracted fact', hash('correction'))])),
      source: 'distill' as const,
      sourceTurnId
    }
    expect(await restarted.apply(f.agentId, DEF_ORG, delayed, NOW)).toMatchObject({
      operation: 'error',
      code: 'CONFLICT'
    })
    expect(await f.read('topic.md')).toBe('correction')
    expect(await prisma.agentMemoryMutation.count({ where: { agentId: f.agentId } })).toBe(1)
  })

  it('isolates capture suppression by agent, memory root and source turn', async () => {
    const f = await fixture()
    const other = await fixture()
    const sourceTurnId = randomUUID()
    receipt(await f.apply({ ...(await f.request([await f.stage('topic.md', 'correction')])), sourceTurnId }))
    for (const scope of [
      { agentId: f.agentId, root: 'memory', sourceTurnId: randomUUID() },
      { agentId: f.agentId, root: 'channels/example/memory', sourceTurnId },
      { agentId: other.agentId, root: 'memory', sourceTurnId }
    ]) {
      const repo = new PgAgentMemoryTransactionRepo(prisma)
      expect(await repo.apply(scope.agentId, DEF_ORG, { ...scope, operation: 'capture-status' }, NOW)).toEqual({
        operation: 'capture-status',
        suppressed: false
      })
    }
  })

  it('does not treat a failed explicit mutation as completed or suppress an already committed replay', async () => {
    const f = await fixture()
    const sourceTurnId = randomUUID()
    const failed = {
      ...(await f.request([await f.stage('topic.md', 'invalid')])),
      expectedRevision: '0'.repeat(64),
      sourceTurnId
    }
    expect(await f.apply(failed)).toMatchObject({ operation: 'error', code: 'CONFLICT' })
    expect(await f.apply({ operation: 'capture-status', agentId: f.agentId, root: 'memory', sourceTurnId })).toEqual({
      operation: 'capture-status',
      suppressed: false
    })
    const capture = {
      ...(await f.request([await f.stage('topic.md', 'captured')])),
      source: 'distill' as const,
      sourceTurnId
    }
    const original = receipt(await f.apply(capture))
    receipt(
      await f.apply({ ...(await f.request([await f.stage('topic.md', 'correction', hash('captured'))])), sourceTurnId })
    )
    expect(await f.apply(capture)).toEqual({ operation: 'commit', receipt: original, replayed: true })
    expect(await f.read('topic.md')).toBe('correction')
  })
})

/**
 * `POST /api/v1/reconcile/slack`: the write-side twin of `check/slack`. The deployment
 * Slack App keeps the scope set it was created with while `SLACK_BOT_SCOPES` grows; this
 * route brings the app's manifest to the expected one with the caller's config token.
 */
import { afterEach, describe, expect, it } from 'vitest'
import type { FastifyInstance } from 'fastify'
import {
  DEFAULT_DEPLOYMENT_CONFIG_VALUES_V1,
  type DeploymentConfigStore,
  type DeploymentConfigValuesV1
} from '@agentconnect.md/control-plane/deployment-config-store'
import type {
  SlackManifestExportResult,
  SlackManifestUpdateResult
} from '@agentconnect.md/control-plane/slack-config-api'
import { buildSetupServer } from '../src/server/index.js'

const STALE_MANIFEST = {
  display_information: { name: 'AgentConnect Test', description: 'keep me' },
  oauth_config: {
    redirect_urls: ['https://api.example.test/v1/integrations/slack/platform/callback'],
    scopes: { bot: ['chat:write', 'channels:history'], user: ['openid', 'email', 'profile'] }
  },
  settings: {
    event_subscriptions: { bot_events: ['app_mention'], request_url: 'https://relay.example.test/slack/events' },
    interactivity: { is_enabled: true, request_url: 'https://relay.example.test/slack/interactions' },
    socket_mode_enabled: false
  }
}

/** Slack's manifest store, in memory: export reads it, update replaces it. */
class FakeSlackConfigApi {
  manifest: Record<string, unknown> = structuredClone(STALE_MANIFEST)
  updates: Record<string, unknown>[] = []
  exportCalls: string[] = []
  async createApp() {
    return { ok: false as const, error: 'unused' }
  }
  async exportApp(configToken: string): Promise<SlackManifestExportResult> {
    this.exportCalls.push(configToken)
    return { ok: true, manifest: this.manifest }
  }
  async updateApp(_token: string, _appId: string, manifest: unknown): Promise<SlackManifestUpdateResult> {
    this.updates.push(manifest as Record<string, unknown>)
    this.manifest = manifest as Record<string, unknown>
    return { ok: true, permissionsUpdated: true }
  }
}

let running: FastifyInstance | undefined
afterEach(async () => {
  await running?.close()
  running = undefined
})

function server(values: DeploymentConfigValuesV1): { app: FastifyInstance; slack: FakeSlackConfigApi } {
  const admin = {
    schemaVersion: 1 as const,
    revision: 4,
    values,
    secrets: [] as { key: string; configured: boolean; fingerprint: string | null; updatedAt: Date | null }[],
    adminClaimedFor: null,
    updatedAt: new Date('2026-09-01T00:00:00.000Z')
  }
  const store = {
    getAdmin: async () => admin,
    getRuntime: async () => null,
    markAdminClaimed: async () => {}
  } as unknown as DeploymentConfigStore
  const slack = new FakeSlackConfigApi()
  const app = buildSetupServer({
    store,
    publicUrl: 'http://localhost:8091',
    slackConfigApi: slack,
    localAuthBootstrap: {
      issuer: 'https://auth.example.test',
      services: {
        web: 'https://console.example.test',
        controlPlane: 'https://api.example.test',
        relay: 'https://relay.example.test'
      }
    }
  })
  running = app
  return { app, slack }
}

const CONFIGURED: DeploymentConfigValuesV1 = {
  ...DEFAULT_DEPLOYMENT_CONFIG_VALUES_V1,
  slack: { appId: 'A0DEPLOY', clientId: '1.1' }
}

const reconcile = (app: FastifyInstance, configToken = 'xoxe.xoxp-temporary') =>
  app.inject({ method: 'POST', url: '/api/v1/reconcile/slack', payload: { configToken } })

describe('POST /api/v1/reconcile/slack', () => {
  it('applies the diff the check reports, keeps user-owned fields, and re-reads the result', async () => {
    const { app, slack } = server(CONFIGURED)

    const res = await reconcile(app)

    expect(res.statusCode).toBe(200)
    const body = res.json() as { status: string; applied: string[]; missing: string[]; permissionsUpdated: boolean }
    expect(body.status).toBe('pass')
    expect(body.missing).toEqual([])
    expect(body.applied).toEqual(expect.arrayContaining(['scope:lists:read', 'scope:im:read', 'event:message.im']))
    expect(body.permissionsUpdated).toBe(true)
    expect(slack.updates).toHaveLength(1)
    const submitted = slack.updates[0]!
    expect((submitted.display_information as { description: string }).description).toBe('keep me')
    expect((submitted.oauth_config as { scopes: { user: string[] } }).scopes.user).toEqual([
      'openid',
      'email',
      'profile'
    ])
    // Export before the write and again after it: the answer is what Slack kept.
    expect(slack.exportCalls).toEqual(['xoxe.xoxp-temporary', 'xoxe.xoxp-temporary'])
    // The token never reaches the browser.
    expect(JSON.stringify(body)).not.toContain('xoxe')
  })

  it('writes nothing when the app already matches', async () => {
    const { app, slack } = server(CONFIGURED)
    await reconcile(app)
    slack.updates = []

    const res = await reconcile(app)

    expect(res.statusCode).toBe(200)
    expect(res.json()).toMatchObject({ status: 'pass', applied: [], permissionsUpdated: false })
    expect(slack.updates).toEqual([])
  })

  it('needs a config token and a configured deployment app', async () => {
    const { app, slack } = server(CONFIGURED)
    expect((await app.inject({ method: 'POST', url: '/api/v1/reconcile/slack', payload: {} })).statusCode).toBe(400)
    expect(slack.updates).toEqual([])

    const bare = server(DEFAULT_DEPLOYMENT_CONFIG_VALUES_V1)
    expect((await reconcile(bare.app)).statusCode).toBe(409)
    expect(bare.slack.updates).toEqual([])
  })
})

import { describe, expect, it } from 'vitest'
import { DEFAULT_DEPLOYMENT_CONFIG_VALUES_V1 } from '@agentconnect.md/control-plane/deployment-config-store'
import { gitlabDeploymentPut, linearDeploymentPut, localAuthLogtoPut } from '../src/deployment-config-client.js'

describe('localAuthLogtoPut', () => {
  it('stores an explicit Logto Management API resource', () => {
    const result = localAuthLogtoPut(
      { values: DEFAULT_DEPLOYMENT_CONFIG_VALUES_V1 },
      {
        managementAppId: 'cloud-m2m-app',
