describe('discoverMcpAuthorization', () => {
  it('walks probe → protected resource → authorization server and reports the audience and scopes', async () => {
    const dial = fakeDial({
      [MCP_URL]: ok(401, undefined, CHALLENGE),
      'https://mcp.example.test/.well-known/oauth-protected-resource/mcp': ok(200, PRM_DOC),
      'https://auth.example.test/.well-known/oauth-authorization-server': ok(200, AS_DOC)
    })
    const result = await discoverMcpAuthorization(dial, MCP_URL)
    expect(result.ok).toBe(true)
    if (!result.ok) return
    expect(result.value.resource).toBe(MCP_URL)
    expect(result.value.scopes).toEqual(['files:read', 'files:write', 'offline_access'])
    expect(result.value.metadata.registrationEndpoint).toBe(`${ISSUER}/register`)
  })

  it('surfaces the first failure in the chain', async () => {
    const dial = fakeDial({ [MCP_URL]: ok(200, { jsonrpc: '2.0', id: 0, result: {} }) })
    expect(await discoverMcpAuthorization(dial, MCP_URL)).toEqual({ ok: false, failure: 'discovery_unreachable' })
  })
})

import { describe, it, expect, vi } from 'vitest'
import { McpProviderTokenService, refreshMarginMs, MIN_REFRESH_MARGIN_MS } from './token-service.js'
import { PlaintextSecretCipher } from '../secrets/cipher.js'
import { OrgId } from '../domain/ids.js'
import type { GuardedResult } from '../net/guarded-fetch.js'
import type { Dial } from './discovery.js'
import type {
  McpProviderOauthRecord,
  McpProviderOauthRepo,
  McpProviderOauthSecretStore,
  McpSealedTokenPair
} from '../persistence/ports.js'

const ORG = OrgId('org-1')
const PROVIDER = 'provider-1'
const NOW = new Date('2026-09-14T12:00:00Z').getTime()

function record(over: Partial<McpProviderOauthRecord> = {}): McpProviderOauthRecord {
  return {
    mcpProviderId: PROVIDER,
    resource: 'https://mcp.example.test/mcp',
    issuer: 'https://auth.example.test',
    authorizationEndpoint: 'https://auth.example.test/authorize',
    tokenEndpoint: 'https://auth.example.test/token',
    registrationEndpoint: null,
    scopes: ['files:read'],
    clientId: 'client-1',
    clientSource: 'dynamic',
    issParameterSupported: true,
    status: 'connected',
    connectedByUserId: null,
    accessExpiresAt: new Date(NOW + 3600_000),
    tokenVersion: 3n,
    createdAt: new Date(NOW - 86_400_000),
    updatedAt: new Date(NOW - 1_800_000),
    ...over
  }
}

/** An in-memory stand-in for the repo + secret store pair, with the CAS the real one has. */
function fakeStore(initial: McpProviderOauthRecord) {
  let row = initial
  let secrets: { clientSecret: string | null; accessToken: string | null; refreshToken: string | null } | null = {
    clientSecret: null,
    accessToken: 'access-1',
    refreshToken: 'refresh-1'
  }
  let leaseOwner: string | null = null
  const calls = { commit: 0, reauth: 0, claim: 0 }
  const oauth: McpProviderOauthRepo = {
    prepare: vi.fn(),
    connect: vi.fn(),
    get: async () => row,
    claimRefreshLease: async (_id: string, owner: string) => {
      calls.claim++
      if (leaseOwner !== null && leaseOwner !== owner) return false
      leaseOwner = owner
      return true
    },
    releaseRefreshLease: async (_id: string, owner: string) => {
      if (leaseOwner === owner) leaseOwner = null
    },
    commitRefresh: async (_id: string, expected: bigint, accessExpiresAt: Date | null, pair: McpSealedTokenPair) => {
      calls.commit++
      if (expected !== row.tokenVersion) return false
      row = { ...row, tokenVersion: row.tokenVersion + 1n, accessExpiresAt, updatedAt: new Date(NOW) }
      secrets = { clientSecret: secrets?.clientSecret ?? null, ...pair }
      return true
    },
    markReauthRequired: async (_id: string, expected: bigint) => {
      calls.reauth++
      if (expected !== row.tokenVersion) return false
      row = { ...row, status: 'reauth_required' }
      return true
    },
    disconnect: vi.fn(),
    dueForRefresh: vi.fn()
  } as unknown as McpProviderOauthRepo
  const store: McpProviderOauthSecretStore = { get: async () => secrets }
  return {
    oauth,
    store,
    calls,
    read: () => row,
    readSecrets: () => secrets,
    /** Simulate a peer advancing the grant while an upstream call is in flight. */
    bumpVersion: () => {
      row = { ...row, tokenVersion: row.tokenVersion + 1n }
    },
    holdLease: (owner: string) => {
      leaseOwner = owner
    },
    clearSecrets: () => {
      secrets = { clientSecret: null, accessToken: 'access-1', refreshToken: null }
    }
  }
}

const tokenResponse = (json: unknown, status = 200): GuardedResult => ({
  ok: true,
  response: { status, headers: {}, text: JSON.stringify(json), json }
})

function service(store: ReturnType<typeof fakeStore>, dial: Dial, owner = 'cp-test') {
  return new McpProviderTokenService({
    oauth: store.oauth,
    secrets: store.store,
    cipher: new PlaintextSecretCipher(),
    dial,
    clock: { now: () => NOW } as never,
    owner
  })
}

describe('refreshMarginMs', () => {
  it('is half the observed lifetime, floored at a minute', () => {
    expect(refreshMarginMs(0, new Date(3600_000))).toBe(1800_000)
    expect(refreshMarginMs(0, new Date(120_000))).toBe(60_000)
    expect(refreshMarginMs(0, new Date(30_000))).toBe(MIN_REFRESH_MARGIN_MS)
    expect(refreshMarginMs(0, null)).toBe(MIN_REFRESH_MARGIN_MS)
  })
})

describe('McpProviderTokenService.resolve', () => {
  it('serves the stored token without dialing while it is comfortably fresh', async () => {
    const store = fakeStore(record())
    const dial = vi.fn() as unknown as Dial
    const result = await service(store, dial).resolve(ORG, PROVIDER)
    expect(result).toEqual({ ok: true, accessToken: 'access-1', expiresAt: new Date(NOW + 3600_000), rotated: false })
    expect(dial).not.toHaveBeenCalled()
  })

  it('refuses a provider that was never authorized or has been disconnected', async () => {
    const store = fakeStore(record({ status: 'pending' }))
    expect(await service(store, vi.fn() as unknown as Dial).resolve(ORG, PROVIDER)).toEqual({
      ok: false,
      reason: 'not_connected'
    })
  })

  it('never dials in cached-only mode, even when the token is due', async () => {
    const store = fakeStore(record({ accessExpiresAt: new Date(NOW + 1_000) }))
    const dial = vi.fn() as unknown as Dial
    const result = await service(store, dial).resolve(ORG, PROVIDER, { allowNetwork: false })
    expect(result).toMatchObject({ ok: true, accessToken: 'access-1', rotated: false })
    expect(dial).not.toHaveBeenCalled()
  })

  it('still hands back the last token for a grant that needs re-authorization', async () => {
    const store = fakeStore(record({ status: 'reauth_required' }))
    const dial = vi.fn() as unknown as Dial
    expect(await service(store, dial).resolve(ORG, PROVIDER)).toMatchObject({ ok: true, accessToken: 'access-1' })
    expect(dial).not.toHaveBeenCalled()
  })

  it('refreshes when the token is inside its margin, persisting the rotated pair', async () => {
    const store = fakeStore(record({ accessExpiresAt: new Date(NOW + 30_000) }))
    const dial = vi.fn(async () =>
      tokenResponse({ access_token: 'access-2', refresh_token: 'refresh-2', expires_in: 3600 })
    ) as unknown as Dial
    const result = await service(store, dial).resolve(ORG, PROVIDER)
    expect(result).toEqual({ ok: true, accessToken: 'access-2', expiresAt: new Date(NOW + 3600_000), rotated: true })
    expect(store.readSecrets()).toMatchObject({ accessToken: 'access-2', refreshToken: 'refresh-2' })
  })

  it('keeps the existing refresh token when the server declines to rotate one', async () => {
    const store = fakeStore(record({ accessExpiresAt: new Date(NOW + 30_000) }))
    const dial = vi.fn(async () => tokenResponse({ access_token: 'access-2', expires_in: 600 })) as unknown as Dial
    expect(await service(store, dial).resolve(ORG, PROVIDER)).toMatchObject({ ok: true, rotated: true })
    expect(store.readSecrets()).toMatchObject({ accessToken: 'access-2', refreshToken: 'refresh-1' })
  })

  it('RE-SEALS a retained refresh token instead of writing back the opened one', async () => {
    // The store opens everything it returns, so a retained token arrives as plaintext. Writing
    // it straight back would silently strip its at-rest encryption under a real cipher.
    const store = fakeStore(record({ accessExpiresAt: new Date(NOW + 30_000) }))
    const sealed: string[] = []
    const cipher = {
      seal: async (v: string) => {
        sealed.push(v)
        return `sealed(${v})`
      },
      open: async (v: string) => (v.startsWith('sealed(') ? v.slice(7, -1) : v)
    }
    const svc = new McpProviderTokenService({
      oauth: store.oauth,
      secrets: store.store,
      cipher: cipher as never,
      dial: (async () => tokenResponse({ access_token: 'access-2', expires_in: 600 })) as unknown as Dial,
      clock: { now: () => NOW } as never,
      owner: 'cp-test'
    })
    expect(await svc.resolve(ORG, PROVIDER)).toMatchObject({ ok: true, rotated: true })
    // Both halves of the committed pair went through the cipher, not just the fresh one.
    expect(sealed).toContain('refresh-1')
    expect(store.readSecrets()).toMatchObject({ refreshToken: 'sealed(refresh-1)' })
  })

  it('collapses concurrent callers into one upstream refresh', async () => {
    const store = fakeStore(record({ accessExpiresAt: new Date(NOW + 30_000) }))
    let dials = 0
    const dial = (async () => {
      dials++
      await new Promise((r) => setTimeout(r, 5))
      return tokenResponse({ access_token: 'access-2', refresh_token: 'refresh-2', expires_in: 3600 })
    }) as unknown as Dial
    const svc = service(store, dial)
    const results = await Promise.all([
      svc.resolve(ORG, PROVIDER),
      svc.resolve(ORG, PROVIDER),
      svc.resolve(ORG, PROVIDER)
    ])
    expect(dials).toBe(1)
    for (const r of results) expect(r).toMatchObject({ ok: true, accessToken: 'access-2' })
  })

  it('serves the stored token instead of racing a peer that already holds the lease', async () => {
    const store = fakeStore(record({ accessExpiresAt: new Date(NOW + 30_000) }))
    store.holdLease('cp-peer')
    const dial = vi.fn() as unknown as Dial
    expect(await service(store, dial).resolve(ORG, PROVIDER)).toMatchObject({ ok: true, accessToken: 'access-1' })
    expect(dial).not.toHaveBeenCalled()
  })

  it('takes the peer write when its own CAS is lost mid-flight', async () => {
    const store = fakeStore(record({ accessExpiresAt: new Date(NOW + 30_000) }))
    const dial = (async () => {
      store.bumpVersion() // a reconnect or a peer landed while we were upstream
      return tokenResponse({ access_token: 'access-2', refresh_token: 'refresh-2', expires_in: 3600 })
    }) as unknown as Dial
    const result = await service(store, dial).resolve(ORG, PROVIDER)
    expect(result).toEqual({ ok: true, accessToken: 'access-1', expiresAt: new Date(NOW + 30_000), rotated: false })
    expect(store.readSecrets()).toMatchObject({ accessToken: 'access-1' })
  })

  it.each([
    [{ status: 400, body: { error: 'invalid_grant' } }, 'reauth_required'],
    [{ status: 401, body: { error: 'invalid_client' } }, 'reauth_required'],
    [{ status: 200, body: { not: 'a token' } }, 'reauth_required']
  ])('treats a definitive refusal as needing re-authorization (%#)', async ({ status, body }, reason) => {
    const store = fakeStore(record({ accessExpiresAt: new Date(NOW + 30_000) }))
    const dial = (async () => tokenResponse(body, status)) as unknown as Dial
    expect(await service(store, dial).resolve(ORG, PROVIDER)).toEqual({ ok: false, reason })
    expect(store.read().status).toBe('reauth_required')
  })

  it.each([[{ ok: false, failure: 'unreachable' } as GuardedResult], [tokenResponse({ error: 'server_error' }, 503)]])(
    'leaves a working grant alone when the server is unreachable (%#)',
    async (response) => {
      const store = fakeStore(record({ accessExpiresAt: new Date(NOW + 30_000) }))
      const dial = (async () => response) as unknown as Dial
      expect(await service(store, dial).resolve(ORG, PROVIDER)).toEqual({ ok: false, reason: 'unreachable' })
      expect(store.read().status).toBe('connected')
      expect(store.calls.reauth).toBe(0)
    }
  )

  it('needs re-authorization once there is no refresh token left to renew with', async () => {
    const store = fakeStore(record({ accessExpiresAt: new Date(NOW + 30_000) }))
    store.clearSecrets()
    const dial = vi.fn() as unknown as Dial
    expect(await service(store, dial).resolve(ORG, PROVIDER)).toEqual({ ok: false, reason: 'reauth_required' })
    expect(dial).not.toHaveBeenCalled()
    expect(store.read().status).toBe('reauth_required')
  })
})

describe('McpProviderTokenService.refresh', () => {
  it('renews regardless of how much life is left', async () => {
    const store = fakeStore(record())
    const dial = vi.fn(async () =>
      tokenResponse({ access_token: 'access-2', refresh_token: 'refresh-2', expires_in: 3600 })
    ) as unknown as Dial
    expect(await service(store, dial).refresh(ORG, PROVIDER)).toMatchObject({ accessToken: 'access-2', rotated: true })
  })

  it('has nothing to renew for a grant that is not connected', async () => {
    const store = fakeStore(record({ status: 'reauth_required' }))
    expect(await service(store, vi.fn() as unknown as Dial).refresh(ORG, PROVIDER)).toEqual({
      ok: false,
      reason: 'reauth_required'
    })
  })
})

import { describe, it, expect } from 'vitest'
import type { GuardedResult } from '../net/guarded-fetch.js'
import type { AuthServerMetadata, Dial } from './discovery.js'
import { clientBindingStale, obtainClient } from './registration.js'

const ISSUER = 'https://auth.example.test'
const REDIRECT_URI = 'https://console.example.test/v1/mcp-providers/oauth/callback'

const AS: AuthServerMetadata = {
  issuer: ISSUER,
  authorizationEndpoint: `${ISSUER}/authorize`,
  tokenEndpoint: `${ISSUER}/token`,
  registrationEndpoint: `${ISSUER}/register`,
  issParameterSupported: true,
  clientIdMetadataDocumentSupported: false
}

function fakeDial(result: GuardedResult): Dial & { bodies: string[] } {
  const bodies: string[] = []
  const dial = ((_url: string, init?: { body?: string }) => {
    if (init?.body !== undefined) bodies.push(init.body)
    return Promise.resolve(result)
  }) as Dial & { bodies: string[] }
  dial.bodies = bodies
  return dial
}

const created = (json: unknown, status = 201): GuardedResult => ({
  ok: true,
  response: { status, headers: {}, text: JSON.stringify(json), json }
})

describe('clientBindingStale', () => {
  it('is false with no stored issuer and true once the issuer moves', () => {
    expect(clientBindingStale(undefined, ISSUER)).toBe(false)
    expect(clientBindingStale(ISSUER, ISSUER)).toBe(false)
    expect(clientBindingStale('https://old.example.test', ISSUER)).toBe(true)
  })
})

describe('obtainClient', () => {
  it('prefers operator-supplied credentials over dynamic registration', async () => {
    const dial = fakeDial(created({ client_id: 'dcr-id' }))
    const result = await obtainClient(dial, {
      metadata: AS,
      redirectUri: REDIRECT_URI,
      preregistered: { clientId: 'manual-id', clientSecret: 'manual-secret' }
    })
    expect(result).toEqual({
      ok: true,
      value: { clientId: 'manual-id', clientSecret: 'manual-secret', source: 'preregistered' }
    })
    expect(dial.bodies).toHaveLength(0)
  })

  it('registers dynamically with the exact callback, a web application type, and refresh_token', async () => {
    const dial = fakeDial(created({ client_id: 'dcr-id', client_secret: 'dcr-secret' }))
    const result = await obtainClient(dial, { metadata: AS, redirectUri: REDIRECT_URI })
    expect(result).toEqual({ ok: true, value: { clientId: 'dcr-id', clientSecret: 'dcr-secret', source: 'dynamic' } })
    expect(JSON.parse(dial.bodies[0]!)).toEqual({
      client_name: 'AgentConnect',
      redirect_uris: [REDIRECT_URI],
      grant_types: ['authorization_code', 'refresh_token'],
      response_types: ['code'],
      application_type: 'web',
      token_endpoint_auth_method: 'none'
    })
  })

  it('accepts a 200 as well as a 201, and omits an absent client_secret', async () => {
    const result = await obtainClient(fakeDial(created({ client_id: 'dcr-id' }, 200)), {
      metadata: AS,
      redirectUri: REDIRECT_URI
    })
    expect(result).toEqual({ ok: true, value: { clientId: 'dcr-id', source: 'dynamic' } })
  })

  it('has nothing to fall back to when the server offers no registration endpoint', async () => {
    const { registrationEndpoint: _drop, ...withoutRegistration } = AS
    const result = await obtainClient(fakeDial(created({ client_id: 'x' })), {
      metadata: withoutRegistration,
      redirectUri: REDIRECT_URI
    })
    expect(result).toEqual({ ok: false, failure: 'no_client_registration' })
  })

  it.each([
    [created({ error: 'invalid_redirect_uri' }, 400), 'registration_rejected'],
    [created({ not_a_client: true }), 'registration_rejected'],
    [{ ok: false, failure: 'unreachable' } as GuardedResult, 'registration_unreachable'],
    [{ ok: false, failure: 'address_blocked' } as GuardedResult, 'registration_unreachable'],
    [{ ok: false, failure: 'malformed_response' } as GuardedResult, 'registration_rejected']
  ])('reports %#', async (response, failure) => {
    const result = await obtainClient(fakeDial(response), { metadata: AS, redirectUri: REDIRECT_URI })
    expect(result).toEqual({ ok: false, failure })
  })
})

/**
 * The MCP-provider authorization funnel over real HTTP and a real database.
 *
 * The unit suite already covers the service's decisions; what only an end-to-end run can
 * catch is the wiring around them. Two things in particular:
 *
 *  - the begin/callback hops must route under BOTH the internal `/api/v1` prefix and the
 *    public `/v1` alias. The redirect_uri is registered with a third-party authorization
 *    server ONCE, in its public form, so mounting one prefix is a failure that appears in
 *    production and nowhere else; and
 *  - a completed funnel must put the access token into the relay binding and must NOT put
 *    it, or anything else sealed, into a DTO.
 */
import { describe, it, expect, afterEach } from 'vitest'
import { randomUUID } from 'node:crypto'
import { prisma } from '../setup.db.js'
import { buildHttpApp, type HttpApp } from '../fakes/build-http.js'
import { PgMcpProviderOauthRepo, PgMcpProviderOauthSecretStore } from '../../src/persistence/index.js'
import { PgMcpProviderOauthStateStore, PgMcpProviderRepo } from '../../src/persistence/index.js'
import { PlaintextSecretCipher } from '../../src/secrets/cipher.js'
import { McpProviderOauthService } from '../../src/mcp-oauth/service.js'
import { McpProviderTokenService } from '../../src/mcp-oauth/token-service.js'
import type { Dial } from '../../src/mcp-oauth/discovery.js'
import type { GuardedResult } from '../../src/net/guarded-fetch.js'
import { OrgId } from '../../src/domain/ids.js'
import { serializeByProvider } from '../../src/http/provider-chain.js'
import { DEFAULT_ORG_ID } from '../../prisma/seed.js'

const ORG = `/api/v1/orgs/${DEFAULT_ORG_ID}`
const PUBLIC_CP = 'https://api.example.test'
const MCP_URL = 'https://mcp.example.test/mcp'
const PRM_URL = 'https://mcp.example.test/.well-known/oauth-protected-resource/mcp'
const ISSUER = 'https://auth.example.test'

const opened: HttpApp[] = []
afterEach(async () => {
  await Promise.all(opened.splice(0).map((a) => a.close()))
})

const ok = (status: number, json: unknown, headers: Record<string, string | string[]> = {}): GuardedResult => ({
  ok: true,
  response: { status, headers, text: JSON.stringify(json ?? null), json }
})

/** A complete, well-behaved authorization server: challenge, metadata, DCR, token. */
function fakeUpstream(over: Record<string, GuardedResult> = {}): Dial {
  const table: Record<string, GuardedResult> = {
    [MCP_URL]: ok(401, undefined, { 'www-authenticate': `Bearer resource_metadata="${PRM_URL}", scope="files:read"` }),
    [PRM_URL]: ok(200, { resource: MCP_URL, authorization_servers: [ISSUER], scopes_supported: ['files:read'] }),
    [`${ISSUER}/.well-known/oauth-authorization-server`]: ok(200, {
      issuer: ISSUER,
      authorization_endpoint: `${ISSUER}/authorize`,
      token_endpoint: `${ISSUER}/token`,
      registration_endpoint: `${ISSUER}/register`,
      authorization_response_iss_parameter_supported: true
    }),
    [`${ISSUER}/register`]: ok(201, { client_id: 'dcr-id' }),
    [`${ISSUER}/token`]: ok(200, { access_token: 'access-1', refresh_token: 'refresh-1', expires_in: 3600 }),
    ...over
  }
  return async (url) => table[url] ?? { ok: false, failure: 'unreachable' }
}

/** Captures what the CP actually broadcasts to the relay pool, so a test can assert the
 *  binding a rotation or a PATCH publishes rather than trusting the route's return value. */
function captureRelay(app: HttpApp): Array<{ frame: string; body: Record<string, unknown> }> {
  const seen: Array<{ frame: string; body: Record<string, unknown> }> = []
  app.relayReg.add({
    relayId: 'relay-test',
    send: (frame: string, body: unknown) => {
      seen.push({ frame, body: body as Record<string, unknown> })
    },
    close: () => {}
  } as never)
  return seen
}

function makeApp(dial: Dial): { app: HttpApp; bound: Array<{ providerId: string; headers: unknown }> } {
  const cipher = new PlaintextSecretCipher()
  const bound: Array<{ providerId: string; headers: unknown }> = []
  const oauth = new McpProviderOauthService({
    providers: new PgMcpProviderRepo(prisma),
    oauth: new PgMcpProviderOauthRepo(prisma),
    secrets: new PgMcpProviderOauthSecretStore(prisma, cipher),
    states: new PgMcpProviderOauthStateStore(prisma),
    cipher,
    dial,
    publicCpUrl: PUBLIC_CP,
    webAppUrl: 'https://console.example.test',
    onConnected: async (orgId, providerId) => {
      const sealed = await new PgMcpProviderOauthSecretStore(prisma, cipher).get(orgId, providerId)
      bound.push({ providerId, headers: [{ name: 'Authorization', value: `Bearer ${sealed?.accessToken}` }] })
    }
  })
  // Mirrors the container's own assembly: token custody is what every live publication
  // resolves an oauth2 provider's header through, and disconnect drops only the binding.
  const tokens = new McpProviderTokenService({
    oauth: new PgMcpProviderOauthRepo(prisma),
    secrets: new PgMcpProviderOauthSecretStore(prisma, cipher),
    cipher,
    dial
  })
  const app = buildHttpApp(prisma, { PUBLIC_CP_URL: PUBLIC_CP }, undefined, undefined, {
    mcpProviderOauth: oauth,
    mcpTokenResolver: tokens,
    mcpOauthUnbind: async (_orgId, provider) => {
      app.deps.relayControl.mcpUnassign({ providerId: provider.id })
    }
  })
  opened.push(app)
  return { app, bound }
}

async function createOauthProvider(app: HttpApp): Promise<string> {
  const res = await app.app.inject({
    method: 'POST',
    url: `${ORG}/mcp-providers`,
    payload: { name: `oauth-${randomUUID().slice(0, 8)}`, url: MCP_URL, auth: 'oauth2', headers: [] }
  })
  expect(res.statusCode).toBe(201)
  return (res.json() as { id: string }).id
}

/** start → begin → callback, over whichever prefix the browser hops are addressed at. */
async function walk(app: HttpApp, providerId: string, prefix: '/api/v1' | '/v1') {
  const started = await app.app.inject({
    method: 'POST',
    url: `${ORG}/mcp-providers/${providerId}/oauth/start`,
    payload: { returnPath: '/tools' }
  })
  expect(started.statusCode).toBe(200)
  const { url } = started.json() as { url: string }
  expect(url.startsWith(`${PUBLIC_CP}/v1/mcp-providers/oauth/begin?state=`)).toBe(true)
  const state = new URL(url).searchParams.get('state')!

  const begun = await app.app.inject({ method: 'GET', url: `${prefix}/mcp-providers/oauth/begin?state=${state}` })
  expect(begun.statusCode).toBe(302)
  const cookie = (begun.headers['set-cookie'] as string).split(';')[0]!
  const authorize = new URL(begun.headers.location as string)

  const done = await app.app.inject({
    method: 'GET',
    url: `${prefix}/mcp-providers/oauth/callback?state=${state}&code=code-1&iss=${encodeURIComponent(ISSUER)}`,
    headers: { cookie }
  })
  return { state, cookie, authorize, done }
}

describe('MCP provider OAuth funnel', () => {
  it.each(['/api/v1', '/v1'] as const)('completes over the %s mount', async (prefix) => {
    const { app, bound } = makeApp(fakeUpstream())
    const providerId = await createOauthProvider(app)
    const { authorize, done } = await walk(app, providerId, prefix)

    expect(authorize.origin + authorize.pathname).toBe(`${ISSUER}/authorize`)
    expect(authorize.searchParams.get('code_challenge_method')).toBe('S256')
    expect(authorize.searchParams.get('resource')).toBe(MCP_URL)
    expect(authorize.searchParams.get('redirect_uri')).toBe(`${PUBLIC_CP}/v1/mcp-providers/oauth/callback`)
    expect(done.statusCode).toBe(302)
    expect(done.headers.location).toBe('https://console.example.test/tools?mcpOauth=connected')
    // The grant landed AND was projected as the binding's injected credential.
    expect(bound).toEqual([{ providerId, headers: [{ name: 'Authorization', value: 'Bearer access-1' }] }])
  })

  it('shows the connection state without ever returning a token', async () => {
    const { app } = makeApp(fakeUpstream())
    const providerId = await createOauthProvider(app)
    await walk(app, providerId, '/api/v1')

    const res = await app.app.inject({ method: 'GET', url: `${ORG}/mcp-providers/${providerId}` })
    expect(res.statusCode).toBe(200)
    const dto = res.json() as { auth: string; oauth?: { status: string; issuer: string } }
    expect(dto.auth).toBe('oauth2')
    expect(dto.oauth).toMatchObject({ status: 'connected', issuer: ISSUER })
    expect(res.body).not.toContain('access-1')
    expect(res.body).not.toContain('refresh-1')
  })

  it('fails a replayed callback closed, with the same result as an unknown state', async () => {
    const { app } = makeApp(fakeUpstream())
    const providerId = await createOauthProvider(app)
    const { state, cookie } = await walk(app, providerId, '/api/v1')
    const replay = await app.app.inject({
      method: 'GET',
      url: `/api/v1/mcp-providers/oauth/callback?state=${state}&code=code-1&iss=${encodeURIComponent(ISSUER)}`,
      headers: { cookie }
    })
    expect(replay.statusCode).toBe(302)
    expect(replay.headers.location).toBe('https://console.example.test/?mcpOauth=state_invalid')
  })

  it('refuses a callback carrying an issuer the funnel did not start with', async () => {
    const { app, bound } = makeApp(fakeUpstream())
    const providerId = await createOauthProvider(app)
    const started = await app.app.inject({
      method: 'POST',
      url: `${ORG}/mcp-providers/${providerId}/oauth/start`,
      payload: { returnPath: '/tools' }
    })
    const state = new URL((started.json() as { url: string }).url).searchParams.get('state')!
    const begun = await app.app.inject({ method: 'GET', url: `/api/v1/mcp-providers/oauth/begin?state=${state}` })
    const cookie = (begun.headers['set-cookie'] as string).split(';')[0]!
    const done = await app.app.inject({
      method: 'GET',
      url: `/api/v1/mcp-providers/oauth/callback?state=${state}&code=code-1&iss=https%3A%2F%2Fevil.example.test`,
      headers: { cookie }
    })
    expect(done.headers.location).toBe('https://console.example.test/tools?mcpOauth=issuer_mismatch')
    expect(bound).toHaveLength(0)
  })

  it('refuses a grant with no refresh token rather than binding one that dies at first expiry', async () => {
    const { app, bound } = makeApp(
      fakeUpstream({ [`${ISSUER}/token`]: ok(200, { access_token: 'access-1', expires_in: 3600 }) })
    )
    const providerId = await createOauthProvider(app)
    const { done } = await walk(app, providerId, '/api/v1')
    expect(done.headers.location).toBe('https://console.example.test/tools?mcpOauth=no_refresh_token')
    expect(bound).toHaveLength(0)
  })

  it('surfaces a server that does not advertise OAuth as its own refusal', async () => {
    const { app } = makeApp(
      fakeUpstream({
        [MCP_URL]: ok(200, { jsonrpc: '2.0', id: 0, result: {} }),
        [PRM_URL]: ok(404, undefined),
        'https://mcp.example.test/.well-known/oauth-protected-resource': ok(404, undefined)
      })
    )
    const providerId = await createOauthProvider(app)
    const started = await app.app.inject({
      method: 'POST',
      url: `${ORG}/mcp-providers/${providerId}/oauth/start`,
      payload: {}
    })
    expect(started.statusCode).toBe(400)
    expect((started.json() as { message: string }).message).toBe('discovery_not_protected')
  })

  it('refuses an oauth2 provider that also carries static headers', async () => {
    const { app } = makeApp(fakeUpstream())
    const res = await app.app.inject({
      method: 'POST',
      url: `${ORG}/mcp-providers`,
      payload: {
        name: `oauth-${randomUUID().slice(0, 8)}`,
        url: MCP_URL,
        auth: 'oauth2',
        headers: [{ name: 'Authorization', value: 'Bearer static' }]
      }
    })
    expect(res.statusCode).toBe(400)
  })

  it('keeps the OAuth credential on the binding across a grant rotation', async () => {
    // The regression: a rotation read the STATIC header set — empty for an oauth2 provider —
    // and republished the binding with no Authorization at all, silently breaking it.
    const { app } = makeApp(fakeUpstream())
    const providerId = await createOauthProvider(app)
    await walk(app, providerId, '/api/v1')
    const relay = captureRelay(app)
    const res = await app.app.inject({
      method: 'POST',
      url: `${ORG}/mcp-providers/${providerId}/grant/rotate`,
      payload: {}
    })
    expect(res.statusCode).toBe(200)
    const assign = relay.filter((f) => f.frame === 'rc/mcp-assign').at(-1)
    expect(assign?.body.headers).toEqual([{ name: 'Authorization', value: 'Bearer access-1' }])
  })

  it('keeps the OAuth credential on the binding across a PATCH', async () => {
    const { app } = makeApp(fakeUpstream())
    const providerId = await createOauthProvider(app)
    await walk(app, providerId, '/api/v1')
    const relay = captureRelay(app)
    const res = await app.app.inject({
      method: 'PATCH',
      url: `${ORG}/mcp-providers/${providerId}`,
      payload: { url: 'https://mcp.example.test/mcp?v=2' }
    })
    expect(res.statusCode).toBe(200)
    const assign = relay.filter((f) => f.frame === 'rc/mcp-assign').at(-1)
    expect(assign?.body.headers).toEqual([{ name: 'Authorization', value: 'Bearer access-1' }])
  })

  it('publishes no binding for a provider that has never been authorized', async () => {
    const { app } = makeApp(fakeUpstream())
    const providerId = await createOauthProvider(app)
    const relay = captureRelay(app)
    const res = await app.app.inject({
      method: 'POST',
      url: `${ORG}/mcp-providers/${providerId}/grant/rotate`,
      payload: {}
    })
    expect(res.statusCode).toBe(200)
    // A binding with an empty credential is worse than none: it would answer calls that then
    // fail upstream, and it would overwrite a real one later.
    expect(relay.filter((f) => f.frame === 'rc/mcp-assign')).toHaveLength(0)
  })

  it('disconnect drops the relay binding but keeps the daemon definition', async () => {
    // The regression: disconnect sent `mcpserver/remove` to every enabling daemon, while a
    // later reconnect republishes only the binding — so the server stayed missing.
    const { app } = makeApp(fakeUpstream())
    const providerId = await createOauthProvider(app)
    await walk(app, providerId, '/api/v1')
    const relay = captureRelay(app)
    const res = await app.app.inject({
      method: 'POST',
      url: `${ORG}/mcp-providers/${providerId}/oauth/disconnect`,
      payload: {}
    })
    expect(res.statusCode).toBe(204)
    expect(relay.filter((f) => f.frame === 'rc/mcp-unassign')).toHaveLength(1)
  })

  it('serializes disconnect with the provider chain, so a racing rebind cannot outlive it', async () => {
    // The hazard: a refresher rebind re-reads this provider INSIDE the chain. If disconnect
    // ran outside it, a rebind that had already read a live credential could publish its
    // binding after the unbind, leaving a callable binding for a revoked grant.
    const { app } = makeApp(fakeUpstream())
    const providerId = await createOauthProvider(app)
    await walk(app, providerId, '/api/v1')
    const provider = await new PgMcpProviderRepo(prisma).get(OrgId(DEFAULT_ORG_ID), providerId)

    let releaseChain: () => void = () => {}
    const held = new Promise<void>((resolve) => {
      releaseChain = resolve
    })
    const order: string[] = []
    // Hold the provider's chain, exactly as an in-flight rebind does.
    const holder = serializeByProvider(DEFAULT_ORG_ID, provider!.name, async () => {
      await held
      order.push('rebind')
    })

    const disconnecting = app.app
      .inject({ method: 'POST', url: `${ORG}/mcp-providers/${providerId}/oauth/disconnect`, payload: {} })
      .then((r) => {
        order.push('disconnect')
        return r
      })

    // Give the request every chance to finish early; it must not, because it now queues.
    await new Promise((r) => setTimeout(r, 150))
    expect(order).toEqual([])

    releaseChain()
    await holder
    const res = await disconnecting
    expect(res.statusCode).toBe(204)
    // The disconnect ran strictly after the chain holder — never interleaved with it.
    expect(order).toEqual(['rebind', 'disconnect'])
  })

  it('disconnects without disturbing the provider or its agent-facing identity', async () => {
    const { app } = makeApp(fakeUpstream())
    const providerId = await createOauthProvider(app)
    await walk(app, providerId, '/api/v1')
    const res = await app.app.inject({
      method: 'POST',
      url: `${ORG}/mcp-providers/${providerId}/oauth/disconnect`,
      payload: {}
    })
    expect(res.statusCode).toBe(204)
    const after = await app.app.inject({ method: 'GET', url: `${ORG}/mcp-providers/${providerId}` })
    const dto = after.json() as { url: string; oauth?: { status: string } }
    expect(dto.oauth?.status).toBe('pending')
    expect(dto.url).toBe(MCP_URL)
    expect(
      await new PgMcpProviderOauthSecretStore(prisma, new PlaintextSecretCipher()).get(
        OrgId(DEFAULT_ORG_ID),
        providerId
      )
    ).toMatchObject({ accessToken: null, refreshToken: null })
  })
})

import { describe, it, expect } from 'vitest'
import { buildAuthorizeUrl, issuerResponseValid, pkceChallenge, pkcePair } from './authorize.js'
import { exchangeCode, refreshGrant, type TokenClient } from './token-endpoint.js'
import type { AuthServerMetadata, Dial } from './discovery.js'
import type { GuardedResult } from '../net/guarded-fetch.js'

const ISSUER = 'https://auth.example.test'
const AS: AuthServerMetadata = {
  issuer: ISSUER,
  authorizationEndpoint: `${ISSUER}/authorize`,
  tokenEndpoint: `${ISSUER}/token`,
  issParameterSupported: true,
  clientIdMetadataDocumentSupported: false
}
const CLIENT: TokenClient = {
  tokenEndpoint: `${ISSUER}/token`,
  clientId: 'client-1',
  resource: 'https://mcp.example.test/mcp/'
}
const NOW = new Date('2026-09-14T12:00:00Z').getTime()

const response = (json: unknown, status = 200): GuardedResult => ({
  ok: true,
  response: { status, headers: {}, text: JSON.stringify(json), json }
})

function recordingDial(result: GuardedResult) {
  const seen: Array<{ url: string; headers?: Record<string, string>; body?: string }> = []
  const dial = (async (url: string, init?: { headers?: Record<string, string>; body?: string }) => {
    seen.push({ url, ...(init?.headers ? { headers: init.headers } : {}), ...(init?.body ? { body: init.body } : {}) })
    return result
  }) as Dial
  return { dial, seen }
}

describe('pkcePair', () => {
  it('produces a fresh S256 pair whose challenge is derivable from the verifier alone', () => {
    const a = pkcePair()
    const b = pkcePair()
    expect(a.verifier).not.toBe(b.verifier)
    expect(pkceChallenge(a.verifier)).toBe(a.challenge)
    expect(a.challenge).not.toContain('=')
  })
})

describe('buildAuthorizeUrl', () => {
  it('carries PKCE S256, the state, and the RFC 8707 resource', () => {
    const url = new URL(
      buildAuthorizeUrl({
        metadata: AS,
        clientId: 'client-1',
        redirectUri: 'https://console.example.test/v1/mcp-providers/oauth/callback',
        state: 'nonce-1',
        codeChallenge: 'challenge-1',
        scopes: ['files:read', 'files:write'],
        resource: 'https://mcp.example.test/mcp'
      })
    )
    expect(Object.fromEntries(url.searchParams)).toEqual({
      response_type: 'code',
      client_id: 'client-1',
      redirect_uri: 'https://console.example.test/v1/mcp-providers/oauth/callback',
      state: 'nonce-1',
      code_challenge: 'challenge-1',
      code_challenge_method: 'S256',
      resource: 'https://mcp.example.test/mcp',
      scope: 'files:read files:write'
    })
  })

  it('omits scope entirely when none is known, rather than sending an empty one', () => {
    const url = new URL(
      buildAuthorizeUrl({
        metadata: AS,
        clientId: 'c',
        redirectUri: 'https://console.example.test/cb',
        state: 's',
        codeChallenge: 'c1',
        scopes: [],
        resource: 'https://mcp.example.test/mcp'
      })
    )
    expect(url.searchParams.has('scope')).toBe(false)
  })

  it('keeps query already present on the authorization endpoint', () => {
    const url = new URL(
      buildAuthorizeUrl({
        metadata: { ...AS, authorizationEndpoint: `${ISSUER}/authorize?tenant=acme` },
        clientId: 'c',
        redirectUri: 'https://console.example.test/cb',
        state: 's',
        codeChallenge: 'c1',
        scopes: [],
        resource: 'https://mcp.example.test/mcp'
      })
    )
    expect(url.searchParams.get('tenant')).toBe('acme')
  })
})

describe('issuerResponseValid — RFC 9207 §2.4', () => {
  it.each([
    ['advertised + present + matching', true, ISSUER, true],
    ['advertised + present + different', true, 'https://evil.example.test', false],
    ['advertised + absent', true, undefined, false],
    ['not advertised + present + matching', false, ISSUER, true],
    ['not advertised + present + different', false, 'https://evil.example.test', false],
    ['not advertised + absent', false, undefined, true]
  ])('%s', (_name, advertised, present, expected) => {
    expect(issuerResponseValid({ advertised, present, expected: ISSUER })).toBe(expected)
  })

  it('compares byte-for-byte, with no normalization of case, slash or port', () => {
    for (const present of [`${ISSUER}/`, 'https://AUTH.EXAMPLE.TEST', `${ISSUER}:443`]) {
      expect(issuerResponseValid({ advertised: true, present, expected: ISSUER })).toBe(false)
    }
  })
})

describe('token endpoint', () => {
  it('redeems a code with the verifier, the redirect and the resource', async () => {
    const { dial, seen } = recordingDial(
      response({ access_token: 'a1', refresh_token: 'r1', expires_in: 3600, scope: 'files:read' })
    )
    const result = await exchangeCode(
      dial,
      CLIENT,
      { code: 'code-1', redirectUri: 'https://console.example.test/cb', codeVerifier: 'verifier-1' },
      NOW
    )
    expect(result).toEqual({
      ok: true,
      grant: { accessToken: 'a1', refreshToken: 'r1', expiresAt: new Date(NOW + 3600_000), scope: 'files:read' }
    })
    expect(Object.fromEntries(new URLSearchParams(seen[0]!.body!))).toEqual({
      grant_type: 'authorization_code',
      code: 'code-1',
      redirect_uri: 'https://console.example.test/cb',
      code_verifier: 'verifier-1',
      client_id: 'client-1',
      // The published audience, trailing slash and all — never re-canonicalized.
      resource: 'https://mcp.example.test/mcp/'
    })
  })

  it('sends a confidential client as HTTP Basic and a public one with no authorization', async () => {
    const withSecret = recordingDial(response({ access_token: 'a1' }))
    await refreshGrant(withSecret.dial, { ...CLIENT, clientSecret: 's3cret' }, 'r1', NOW)
    expect(withSecret.seen[0]?.headers?.authorization).toBe(
      `Basic ${Buffer.from('client-1:s3cret').toString('base64')}`
    )
    const withoutSecret = recordingDial(response({ access_token: 'a1' }))
    await refreshGrant(withoutSecret.dial, CLIENT, 'r1', NOW)
    expect(withoutSecret.seen[0]?.headers?.authorization).toBeUndefined()
  })

  it('renews with the refresh grant and carries the resource there too', async () => {
    const { dial, seen } = recordingDial(response({ access_token: 'a2', expires_in: 600 }))
    const result = await refreshGrant(dial, CLIENT, 'r1', NOW)
    expect(result).toEqual({ ok: true, grant: { accessToken: 'a2', expiresAt: new Date(NOW + 600_000) } })
    expect(Object.fromEntries(new URLSearchParams(seen[0]!.body!))).toMatchObject({
      grant_type: 'refresh_token',
      refresh_token: 'r1',
      resource: 'https://mcp.example.test/mcp/'
    })
  })

  it('reports no expiry when the server advertises none', async () => {
    const { dial } = recordingDial(response({ access_token: 'a2' }))
    expect(await refreshGrant(dial, CLIENT, 'r1', NOW)).toEqual({
      ok: true,
      grant: { accessToken: 'a2', expiresAt: null }
    })
  })

  it.each([
    [response({ error: 'invalid_grant' }, 400), 'rejected'],
    [response({ error: 'invalid_client' }, 401), 'rejected'],
    [response({ error: 'server_error' }, 500), 'unreachable'],
    [response({ error: 'bad_gateway' }, 502), 'unreachable'],
    [response({ no_token: true }, 200), 'malformed'],
    [{ ok: false, failure: 'unreachable' } as GuardedResult, 'unreachable'],
    [{ ok: false, failure: 'address_blocked' } as GuardedResult, 'unreachable'],
    [{ ok: false, failure: 'malformed_response' } as GuardedResult, 'malformed']
  ])('separates a definitive refusal from learning nothing (%#)', async (result, failure) => {
    const { dial } = recordingDial(result)
    expect(await refreshGrant(dial, CLIENT, 'r1', NOW)).toEqual({ ok: false, failure })
  })
})

/**
 * PgMcpProviderOauthRepo / SecretStore / StateStore — the two properties the whole OAuth
 * design rests on (docs/designs/mcp-provider-oauth.md):
 *
 *  - a token pair is only ever visible together with the `tokenVersion` it was minted
 *    against, so no reader sees a `connected` row holding a stale or missing pair; and
 *  - any write that changes user intent advances that version, so a refresh already in
 *    flight loses its CAS instead of resurrecting a grant that was just replaced or revoked.
 *
 * Both are enforced in transactions inside the repo, which is why they are tested here
 * against a real Postgres rather than against a fake.
 */
import { describe, it, expect } from 'vitest'
import { prisma } from '../setup.db.js'
import { randomUUID } from 'node:crypto'
import {
  PgMcpProviderOauthRepo,
  PgMcpProviderOauthSecretStore,
  PgMcpProviderOauthStateStore,
  PgMcpProviderRepo
} from '../../src/persistence/index.js'
import { PlaintextSecretCipher } from '../../src/secrets/cipher.js'
import { OrgId } from '../../src/domain/ids.js'
import { DEFAULT_ORG_ID } from '../../prisma/seed.js'
import type { PrepareMcpProviderOauthInput } from '../../src/persistence/ports.js'

const ORG = OrgId(DEFAULT_ORG_ID)
const OTHER_ORG = OrgId('org-not-ours')
const ISSUER = 'https://auth.example.test'

const repo = (): PgMcpProviderOauthRepo => new PgMcpProviderOauthRepo(prisma)
const secrets = (): PgMcpProviderOauthSecretStore =>
  new PgMcpProviderOauthSecretStore(prisma, new PlaintextSecretCipher())
const states = (): PgMcpProviderOauthStateStore => new PgMcpProviderOauthStateStore(prisma)

const PREPARED: PrepareMcpProviderOauthInput = {
  resource: 'https://mcp.example.test/mcp',
  issuer: ISSUER,
  authorizationEndpoint: `${ISSUER}/authorize`,
  tokenEndpoint: `${ISSUER}/token`,
  registrationEndpoint: `${ISSUER}/register`,
  scopes: ['files:read'],
  clientId: 'client-1',
  clientSource: 'dynamic',
  issParameterSupported: true,
  sealedClientSecret: 'client-secret-1'
}

async function makeProvider(name = `oauth-${randomUUID().slice(0, 8)}`): Promise<string> {
  const row = await new PgMcpProviderRepo(prisma).create({
    orgId: ORG,
    name,
    url: 'https://mcp.example.test/mcp',
    auth: 'oauth2'
  })
  return row.id
}

/** Prepare + connect, the ordinary path a completed funnel takes. */
async function connected(): Promise<{ providerId: string; version: bigint }> {
  const providerId = await makeProvider()
  const prepared = await repo().prepare(ORG, providerId, PREPARED)
  expect(
    await repo().connect(ORG, providerId, {
      expectedVersion: prepared.tokenVersion,
      accessExpiresAt: new Date(Date.now() + 3600_000),
      connectedByUserId: null,
      sealedPair: { accessToken: 'access-1', refreshToken: 'refresh-1' }
    })
  ).toBe(true)
  const row = await repo().get(ORG, providerId)
  return { providerId, version: row!.tokenVersion }
}

describe('PgMcpProviderOauthRepo', () => {
  it('records the published resource verbatim and keeps the row pending until a grant lands', async () => {
    const providerId = await makeProvider()
    const row = await repo().prepare(ORG, providerId, { ...PREPARED, resource: 'https://mcp.example.test/mcp/' })
    expect(row.status).toBe('pending')
    expect(row.resource).toBe('https://mcp.example.test/mcp/')
    expect(row.clientSource).toBe('dynamic')
    expect(await secrets().get(ORG, providerId)).toEqual({
      clientSecret: 'client-secret-1',
      accessToken: null,
      refreshToken: null
    })
  })

  it('publishes the pair and the connected status together', async () => {
    const { providerId } = await connected()
    const row = await repo().get(ORG, providerId)
    expect(row?.status).toBe('connected')
    expect(await secrets().get(ORG, providerId)).toMatchObject({ accessToken: 'access-1', refreshToken: 'refresh-1' })
  })

  it('commits a refresh under the version CAS and refuses a stale one', async () => {
    const { providerId, version } = await connected()
    const later = new Date(Date.now() + 7200_000)
    expect(await repo().commitRefresh(providerId, version, later, { accessToken: 'a2', refreshToken: 'r2' })).toBe(true)
    // The same expected version again is exactly what a second flight holding a spent
    // refresh token would present. It must not land.
    expect(await repo().commitRefresh(providerId, version, later, { accessToken: 'a3', refreshToken: 'r3' })).toBe(
      false
    )
    expect(await secrets().get(ORG, providerId)).toMatchObject({ accessToken: 'a2', refreshToken: 'r2' })
  })

  it('lets a re-run of the funnel void a pair minted against the old client identity', async () => {
    const { providerId, version } = await connected()
    await repo().prepare(ORG, providerId, { ...PREPARED, clientId: 'client-2' })
    const reprepared = await repo().get(ORG, providerId)
    expect(reprepared?.status).toBe('pending')
    expect(reprepared?.clientId).toBe('client-2')
    expect(await secrets().get(ORG, providerId)).toEqual({
      clientSecret: 'client-secret-1',
      accessToken: null,
      refreshToken: null
    })
    // A refresh that was already in flight against the previous identity loses.
    expect(await repo().commitRefresh(providerId, version, new Date(), { accessToken: 'x', refreshToken: 'y' })).toBe(
      false
    )
  })

  it('disconnects atomically and defeats an in-flight refresh CAS', async () => {
    const { providerId, version } = await connected()
    expect(await repo().disconnect(ORG, providerId)).toBe(true)
    const row = await repo().get(ORG, providerId)
    expect(row?.status).toBe('pending')
    expect(row?.accessExpiresAt).toBeNull()
    expect(await secrets().get(ORG, providerId)).toMatchObject({ accessToken: null, refreshToken: null })
    expect(await repo().commitRefresh(providerId, version, new Date(), { accessToken: 'x', refreshToken: 'y' })).toBe(
      false
    )
  })

  it('fences every org-addressed method through the parent provider', async () => {
    const { providerId } = await connected()
    expect(await repo().get(OTHER_ORG, providerId)).toBeNull()
    expect(await secrets().get(OTHER_ORG, providerId)).toBeNull()
    expect(await repo().disconnect(OTHER_ORG, providerId)).toBe(false)
    await expect(repo().prepare(OTHER_ORG, providerId, PREPARED)).rejects.toThrow()
  })

  it('elects one lease holder, and hands an expired lease to the next claimant', async () => {
    const { providerId } = await connected()
    const now = new Date()
    const until = new Date(now.getTime() + 30_000)
    expect(await repo().claimRefreshLease(providerId, 'cp-a', until, now)).toBe(true)
    expect(await repo().claimRefreshLease(providerId, 'cp-b', until, now)).toBe(false)
    // Re-entrant for the holder, and claimable again once the lease has lapsed (crash recovery).
    expect(await repo().claimRefreshLease(providerId, 'cp-a', until, now)).toBe(true)
    expect(await repo().claimRefreshLease(providerId, 'cp-b', until, new Date(until.getTime() + 1_000))).toBe(true)
    await repo().releaseRefreshLease(providerId, 'cp-b')
    expect(await repo().claimRefreshLease(providerId, 'cp-c', until, now)).toBe(true)
  })

  it('marks reauth_required only at the version the outcome was produced at', async () => {
    const { providerId, version } = await connected()
    expect(await repo().markReauthRequired(providerId, version - 1n)).toBe(false)
    expect(await repo().markReauthRequired(providerId, version)).toBe(true)
    expect((await repo().get(ORG, providerId))?.status).toBe('reauth_required')
  })

  it('sweeps connected rows due for renewal, with the org and name the re-push needs', async () => {
    const { providerId } = await connected()
    const soon = await makeProvider()
    const prepared = await repo().prepare(ORG, soon, PREPARED)
    await repo().connect(ORG, soon, {
      expectedVersion: prepared.tokenVersion,
      accessExpiresAt: new Date(Date.now() + 30_000),
      connectedByUserId: null,
      sealedPair: { accessToken: 'a', refreshToken: 'r' }
    })
    const due = await repo().dueForRefresh(new Date(Date.now() + 60_000), 50)
    expect(due.map((d) => d.mcpProviderId)).toContain(soon)
    expect(due.map((d) => d.mcpProviderId)).not.toContain(providerId)
    expect(due.find((d) => d.mcpProviderId === soon)?.orgId).toBe(DEFAULT_ORG_ID)
    expect(due.find((d) => d.mcpProviderId === soon)?.providerName).toEqual(expect.stringContaining('oauth-'))
  })

  it('never sweeps a row that is pending or needs reauthorization', async () => {
    const providerId = await makeProvider()
    await repo().prepare(ORG, providerId, PREPARED)
    const far = new Date(Date.now() + 86_400_000)
    expect((await repo().dueForRefresh(far, 50)).map((d) => d.mcpProviderId)).not.toContain(providerId)
  })
})

describe('PgMcpProviderOauthStateStore', () => {
  const row = (nonce: string, providerId: string, expiresAt: Date) => ({
    nonce,
    mcpProviderId: providerId,
    orgId: DEFAULT_ORG_ID,
    userId: 'user-1',
    returnPath: '/tools',
    verifier: 'sealed-verifier',
    expectedIssuer: ISSUER,
    expectedVersion: 1n,
    expiresAt
  })

  it('binds the browser exactly once, and reads the same way for a replay as for a forgery', async () => {
    const providerId = await makeProvider()
    const nonce = randomUUID()
    await states().put(row(nonce, providerId, new Date(Date.now() + 900_000)))
    const bound = await states().bindBrowser(nonce, 'hash-1', new Date())
    expect(bound?.expectedIssuer).toBe(ISSUER)
    expect(await states().bindBrowser(nonce, 'hash-2', new Date())).toBeNull()
    expect(await states().bindBrowser(randomUUID(), 'hash-2', new Date())).toBeNull()
  })

  it('refuses to bind an already-expired row', async () => {
    const providerId = await makeProvider()
    const nonce = randomUUID()
    await states().put(row(nonce, providerId, new Date(Date.now() - 1_000)))
    expect(await states().bindBrowser(nonce, 'hash-1', new Date())).toBeNull()
  })

  it('consumes exactly once, and treats an expired row as consumed', async () => {
    const providerId = await makeProvider()
    const fresh = randomUUID()
    await states().put(row(fresh, providerId, new Date(Date.now() + 900_000)))
    expect((await states().consume(fresh, new Date()))?.returnPath).toBe('/tools')
    expect(await states().consume(fresh, new Date())).toBeNull()

    const stale = randomUUID()
    await states().put(row(stale, providerId, new Date(Date.now() - 1_000)))
    expect(await states().consume(stale, new Date())).toBeNull()
  })

  it('reaps expired rows so an abandoned funnel does not keep a sealed verifier around', async () => {
    const providerId = await makeProvider()
    const stale = randomUUID()
    const live = randomUUID()
    await states().put(row(stale, providerId, new Date(Date.now() - 1_000)))
    await states().put(row(live, providerId, new Date(Date.now() + 900_000)))
    expect(await states().reapExpired(new Date())).toBeGreaterThanOrEqual(1)
    expect(await states().consume(stale, new Date())).toBeNull()
    expect(await states().consume(live, new Date())).not.toBeNull()
  })
})

import { describe, it, expect, vi } from 'vitest'
import { McpOauthDenied, McpProviderOauthService, normalizeReturnPath } from './service.js'
import { PlaintextSecretCipher } from '../secrets/cipher.js'
import { OrgId } from '../domain/ids.js'
import type { GuardedResult } from '../net/guarded-fetch.js'
import type { Dial } from './discovery.js'
import type {
  McpProviderOauthRecord,
  McpProviderOauthRepo,
  McpProviderOauthSecretStore,
  McpProviderOauthStateRecord,
  McpProviderOauthStateStore,
  McpProviderRecord,
  McpProviderRepo,
  PrepareMcpProviderOauthInput
} from '../persistence/ports.js'

const ORG = OrgId('org-1')
const PROVIDER = 'provider-1'
const USER = 'user-1'
const MCP_URL = 'https://mcp.example.test/mcp'
const ISSUER = 'https://auth.example.test'
const CP = 'https://cp.example.test'
const WEB = 'https://console.example.test'
const NOW = new Date('2026-09-14T12:00:00Z').getTime()
const CALLBACK = `${CP}/v1/mcp-providers/oauth/callback`
const PRM_URL = 'https://mcp.example.test/.well-known/oauth-protected-resource/mcp'

const ok = (status: number, json: unknown, headers: Record<string, string | string[]> = {}): GuardedResult => ({
  ok: true,
  response: { status, headers, text: JSON.stringify(json ?? null), json }
})

const AS_DOC = {
  issuer: ISSUER,
  authorization_endpoint: `${ISSUER}/authorize`,
  token_endpoint: `${ISSUER}/token`,
  registration_endpoint: `${ISSUER}/register`,
  scopes_supported: ['files:read'],
  authorization_response_iss_parameter_supported: true
}

/** The full discovery + registration + token surface a happy funnel walks. */
function fakeDial(over: Record<string, GuardedResult> = {}) {
  const seen: Array<{ url: string; body?: string }> = []
  const table: Record<string, GuardedResult> = {
    [MCP_URL]: ok(401, undefined, {
      'www-authenticate': `Bearer resource_metadata="${PRM_URL}", scope="files:read"`
    }),
    [PRM_URL]: ok(200, {
      resource: MCP_URL,
      authorization_servers: [ISSUER],
      scopes_supported: ['files:read']
    }),
    'https://auth.example.test/.well-known/oauth-authorization-server': ok(200, AS_DOC),
    [`${ISSUER}/register`]: ok(201, { client_id: 'dcr-id', client_secret: 'dcr-secret' }),
    [`${ISSUER}/token`]: ok(200, { access_token: 'access-1', refresh_token: 'refresh-1', expires_in: 3600 }),
    ...over
  }
  const dial = (async (url: string, init?: { body?: string }) => {
    seen.push({ url, ...(init?.body ? { body: init.body } : {}) })
    return table[url] ?? { ok: false, failure: 'unreachable' }
  }) as Dial
  return { dial, seen }
}

function fakeWorld(providerOver: Partial<McpProviderRecord> = {}) {
  const provider: McpProviderRecord = {
    id: PROVIDER,
    orgId: ORG,
    name: 'linear',
    kind: 'custom',
    auth: 'oauth2',
    ui: false,
    transport: 'http',
    url: MCP_URL,
    visibility: 'org',
    sharedWith: [],
    createdByUserId: null,
    createdAt: new Date(NOW),
    updatedAt: new Date(NOW),
    ...providerOver
  }
  let row: McpProviderOauthRecord | null = null
  let secrets: { clientSecret: string | null; accessToken: string | null; refreshToken: string | null } | null = null
  const stateRows = new Map<string, McpProviderOauthStateRecord>()
  const connected: Array<{ providerId: string; accessExpiresAt: Date | null }> = []

  const providers = { get: async () => (providerOver.url === 'gone' ? null : provider) } as unknown as McpProviderRepo
  const oauth = {
    prepare: async (_o: OrgId, id: string, input: PrepareMcpProviderOauthInput) => {
      row = {
        mcpProviderId: id,
        resource: input.resource,
        issuer: input.issuer,
        authorizationEndpoint: input.authorizationEndpoint,
        tokenEndpoint: input.tokenEndpoint,
        registrationEndpoint: input.registrationEndpoint ?? null,
        scopes: input.scopes,
        clientId: input.clientId,
        clientSource: input.clientSource,
        issParameterSupported: input.issParameterSupported,
        status: 'pending',
        connectedByUserId: null,
        accessExpiresAt: null,
        tokenVersion: (row?.tokenVersion ?? 0n) + 1n,
        createdAt: new Date(NOW),
        updatedAt: new Date(NOW)
      }
      secrets = { clientSecret: input.sealedClientSecret ?? null, accessToken: null, refreshToken: null }
      return row
    },
    get: async () => row,
    connect: async (_o: OrgId, id: string, input: { expectedVersion: bigint; accessExpiresAt: Date | null }) => {
      // The real repo's CAS: a callback whose generation has moved on commits nothing.
      if (row === null || input.expectedVersion !== row.tokenVersion) return false
      connected.push({ providerId: id, accessExpiresAt: input.accessExpiresAt })
      row = { ...row, status: 'connected', accessExpiresAt: input.accessExpiresAt, tokenVersion: row.tokenVersion + 1n }
      return true
    },
    disconnect: async () => {
      // Disconnect advances the generation, exactly as the repo does.
      if (row) row = { ...row, status: 'pending', tokenVersion: row.tokenVersion + 1n }
      return true
    }
  } as unknown as McpProviderOauthRepo
  const store: McpProviderOauthSecretStore = { get: async () => secrets }
  const states: McpProviderOauthStateStore = {
    put: async (r) => {
      stateRows.set(r.nonce, { ...r, browserHash: null })
    },
    bindBrowser: async (nonce, hash, now) => {
      const r = stateRows.get(nonce)
      if (!r || r.browserHash !== null || r.expiresAt <= now) return null
      const bound = { ...r, browserHash: hash }
      stateRows.set(nonce, bound)
      return bound
    },
    consume: async (nonce, now) => {
      const r = stateRows.get(nonce)
      stateRows.delete(nonce)
      return r && r.expiresAt > now ? r : null
    },
    reapExpired: async () => 0
  }
  return { providers, oauth, store, states, stateRows, connected, read: () => row }
}

function service(world: ReturnType<typeof fakeWorld>, dial: Dial, over: Record<string, unknown> = {}) {
  return new McpProviderOauthService({
    providers: world.providers,
    oauth: world.oauth,
    secrets: world.store,
    states: world.states,
    cipher: new PlaintextSecretCipher(),
    dial,
    clock: { now: () => NOW } as never,
    publicCpUrl: CP,
    webAppUrl: WEB,
    ...over
  })
}

/** start → begin → callback, returning what each hop produced. */
async function walk(world: ReturnType<typeof fakeWorld>, dial: Dial, svc = service(world, dial)) {
  const { url } = await svc.start({ orgId: ORG, providerId: PROVIDER, userId: USER, returnPath: '/tools' })
  const nonce = new URL(url).searchParams.get('state')!
  const begun = await svc.begin(nonce)
  const authorize = new URL(begun!.redirectUrl)
  const result = await svc.callback({
    state: nonce,
    code: 'code-1',
    iss: ISSUER,
    error: undefined,
    browserNonce: begun!.browserNonce
  })
  return { svc, nonce, begun, authorize, result }
}

describe('normalizeReturnPath', () => {
  it('accepts a local console path and defaults to root', () => {
    expect(normalizeReturnPath(undefined)).toBe('/')
    expect(normalizeReturnPath('/tools?tab=mcp')).toBe('/tools?tab=mcp')
